function fillSpecList(items){const root=$('#spec-list');if(!root)return;root.replaceChildren(...items.filter(Boolean).map(item=>{const li=document.createElement('li');if(Array.isArray(item)){const title=String(item[0]||'').trim();const desc=String(item[1]||'').trim();if(title&&desc&&title.toLowerCase()!==desc.toLowerCase()){const b=document.createElement('strong');b.textContent=title;li.append(b,document.createTextNode(' — '+desc))}else{li.textContent=title||desc}}else{li.textContent=String(item)}return li}))}function fillNoteList(id,items){const root=$('#'+id);if(!root)return;root.replaceChildren(...items.map(t=>{const p=document.createElement('p');p.className='plain-note';p.textContent=t;return p}))}
function fillActionNotes(items){const root=$('#spec-actions');if(!root)return;root.replaceChildren(...items.map(([name,desc],i)=>{const item=document.createElement('div');item.className='action-note';const number=document.createElement('span');number.className='action-number';number.textContent=String(i+1).padStart(2,'0');const body=document.createElement('div');const title=document.createElement('strong');title.textContent=name;const detail=document.createElement('p');detail.textContent=desc;body.append(title,detail);item.append(number,body);return item}))}
actionGuides.myprofile=[['Edit profile','Opens Edit profile; saving updates identity card, profile sections and completeness'],['Profile settings','Opens app settings'],['Privacy & safety','Opens privacy controls; discovery remains opt-in']];
function fillNoteList(id, arr){
  const el = $('#' + id);
  if(!el) return;
  el.replaceChildren(...(arr || []).map(t => {
    const li = document.createElement('li');
    li.innerHTML = t;
    return li;
  }));
}

