function initSocialMediaInteractions() {
  const pills = all('#ds-content .sm-filter-pill');
  const postCards = all('#ds-content .sm-post-card');
  const storyCol = $('#ds-content .sm-story-col');

  pills.forEach(pill => {
    pill.addEventListener('click', () => {
      pills.forEach(p => {
        p.classList.remove('active');
        p.setAttribute('aria-selected', 'false');
      });
      pill.classList.add('active');
      pill.setAttribute('aria-selected', 'true');

      const filter = pill.dataset.smFilter;
      postCards.forEach(card => {
        if (filter === 'all' || filter === 'stories') {
          card.hidden = false;
        } else {
          card.hidden = card.dataset.category !== filter;
        }
      });

      if (storyCol) {
        if (filter === 'all' || filter === 'stories') {
          storyCol.style.opacity = '1';
          storyCol.style.pointerEvents = 'auto';
        } else {
          storyCol.style.opacity = '0.25';
          storyCol.style.pointerEvents = 'none';
        }
      }
    });
  });

  const slides = all('#ds-content .sm-carousel-slide');
  const dots = all('#ds-content .sm-carousel-dot');
  const nextBtn = $('#ds-content #sm-carousel-next');
  const counter = $('#ds-content #sm-carousel-counter');
  let currentSlide = 0;

  function setSlide(idx) {
    currentSlide = (idx + slides.length) % slides.length;
    dots.forEach((dot, i) => {
      dot.classList.toggle('active', i === currentSlide);
    });
    if (counter) counter.textContent = `${currentSlide + 1} / ${slides.length}`;
    if (slides[currentSlide]) {
      slides[currentSlide].focus({ preventScroll: true });
    }
  }

  if (nextBtn) {
    nextBtn.addEventListener('click', () => setSlide(currentSlide + 1));
  }
  dots.forEach(dot => {
    dot.addEventListener('click', () => {
      const idx = parseInt(dot.dataset.dotIndex, 10);
      setSlide(idx);
    });
  });

  all('#ds-content [data-export^="sm-"]').forEach(btn => {
    btn.addEventListener('click', () => {
      const exportType = btn.dataset.export;
      let svgData = '';
      let filename = btn.dataset.file || 'peopi-template.svg';

      if (exportType === 'sm-post-templates') {
        svgData = getSocialSvgArtwork('post-product');
      } else if (exportType === 'sm-story-templates') {
        svgData = getSocialSvgArtwork('story');
      } else if (exportType === 'sm-brand-assets') {
        svgData = getSocialSvgArtwork('brand-assets');
      }

      if (svgData) {
        const blob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
      }
    });
  });
}



