const PEOPI_VOICE_MARKDOWN = `# PEOPI BRAND VOICE & MESSAGING
Proposed guidelines · Status: Proposed guidelines (v1.0)
Brand Font: Manrope | Brand Color: #FF3300 (Peopi Orange)

---

## 1. CORE MESSAGE
Meet what’s next.
Peopi helps professionals discover people nearby who are open to connecting, send a connection request and build their network.
Attributes: Nearby · Intentional · On your terms

---

## 2. VOICE PRINCIPLES
1. Human: Speak like a person, not a platform.
2. Clear: Say what happens next.
3. Inviting: Offer a next step without pressure.
4. Respectful: Put choice and privacy first.

---

## 3. MESSAGING EXAMPLES
- Introduce Peopi (Bios / Introductions):
  "Professional connections, closer to you."
- Invite someone (Social posts / Campaigns):
  "Open to meeting someone new?"
- Explain discovery (Product education):
  "Choose when you’re open to connecting."

---

## 4. DO / DON’T PHRASING
- [DO] "Open to a new conversation?"
  [DON'T] "Don’t miss your next big opportunity!"
  Rationale: Invite without pressure.

- [DO] "You’re connected. Say hello when you’re ready."
  [DON'T] "You matched! Start chatting now!"
  Rationale: Describe connections accurately.

- [DO] "You control when you’re visible in discovery."
  [DON'T] "Everyone nearby can find you."
  Rationale: Explain privacy without exaggeration.

---

## 5. TONE BY CONTEXT
- Marketing (Warm and curious):
  "Good things start with showing up."
- Product (Short and helpful):
  "Send a connection request."
- Support (Calm and specific):
  "We couldn’t send your request. Please try again."

---

## 6. SHARED VOCABULARY
- Connection: An accepted professional relationship.
- Connection request: An invitation to connect.
- Live presence: Your current discovery visibility.
- I’m Open: The user’s choice to start an active discovery session.
- Hidden connection: An existing connection from whom you hide your live presence while keeping the connection and messaging. (Not blocking. The other person is not notified.)

*Note: Avoid dating language, urgency, and guaranteed outcomes.
`;

function copyFullVoiceKit() {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(PEOPI_VOICE_MARKDOWN).then(() => {
      toast('Full messaging kit copied to clipboard');
    }).catch(err => {
      console.warn('Clipboard failed', err);
      toast('Failed to copy to clipboard. Please copy manually.');
    });
  } else {
    toast('Clipboard unavailable in this browser environment.');
  }
}

function downloadVoiceMarkdownGuide() {
  try {
    const blob = new Blob([PEOPI_VOICE_MARKDOWN], { type: 'text/markdown;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'peopi-brand-voice-messaging-guide.md';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast('Downloaded brand voice & messaging guide');
  } catch (err) {
    console.error('Download failed', err);
    toast('Download failed. Please try again.');
  }
}

function initVoiceGuideInteractions() {
  // Individual copy buttons
  all('#ds-content [data-copy-voice]').forEach(btn => {
    btn.addEventListener('click', () => {
      const textToCopy = btn.dataset.copyVoice;
      if (!textToCopy) return;
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(textToCopy).then(() => {
          toast(`Copied: "${textToCopy}"`);
          const icon = btn.querySelector('i');
          if (icon) {
            icon.className = 'ph ph-check';
            setTimeout(() => { icon.className = 'ph ph-copy'; }, 1500);
          }
        }).catch(err => {
          toast('Unable to copy text to clipboard.');
        });
      } else {
        toast('Clipboard not supported.');
      }
    });
  });

  // Toolkit buttons
  const copyKitBtn = $('#ds-content #btn-voice-copy-kit');
  if (copyKitBtn) {
    copyKitBtn.addEventListener('click', () => copyFullVoiceKit());
  }

  const downloadGuideBtn = $('#ds-content #btn-voice-download-guide');
  if (downloadGuideBtn) {
    downloadGuideBtn.addEventListener('click', () => downloadVoiceMarkdownGuide());
  }
}



