function b64ToUint8Array(b64) {
  const bin = atob(b64);
  const len = bin.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = bin.charCodeAt(i);
  }
  return bytes;
}

function downloadSingleBinaryFile(b64, filename, mimeType) {
  try {
    const bytes = b64ToUint8Array(b64);
    const blob = new Blob([bytes], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast(`Downloaded: ${filename}`);
  } catch (err) {
    console.error('Download failed', err);
    toast('Download failed. Please try again.');
  }
}

function downloadPresentationZipKit() {
  try {
    const pptxBytes = b64ToUint8Array(PEOPI_PPTX_B64);
    const docxBytes = b64ToUint8Array(PEOPI_DOCX_B64);
    const pdfBytes = b64ToUint8Array(PEOPI_PDF_B64);

    const files = [
      { name: 'README-usage-guide.md', content: PEOPI_USAGE_GUIDE_MD },
      { name: 'presentation/peopi-presentation-deck-16x9.pptx', content: pptxBytes },
      { name: 'one-pager/peopi-product-one-pager-A4.pdf', content: pdfBytes },
      { name: 'one-pager/peopi-product-one-pager-editable.docx', content: docxBytes }
    ];

    const blob = createZipArchive(files);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'peopi-presentation-kit.zip';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast('Downloaded: peopi-presentation-kit.zip');
  } catch (err) {
    console.error('ZIP download failed', err);
    toast('Download failed. Please try again.');
  }
}

