const PEOPI_PHOTO_EXPORT_GUIDE_MD = `# PEOPI PHOTOGRAPHY & GRAPHIC STYLE GUIDELINES
Status: Proposed guidelines (v1.0)
Verification Date: October 2026
Document: BRAND APPLICATIONS / G07

---

## 1. PHOTOGRAPHY DIRECTION
- Natural Light & Environments: Emphasize natural daylight and authentic working spaces (cafes, open coworking desks, public lobbies).
- Genuine Interactions: Capture candid, real moments of mutual exchange and focused collaboration.
- Inclusive Representation: Diverse ages, professions, ethnicities, and perspectives.
- Absolute Cliché Prohibitions:
  * NO dating, romantic intimacy, or romanticized coupling poses.
  * NO rigid, generic corporate handshake or staged stock boardroom poses.
  * NO forced artificial branding: do NOT Photoshop Peopi logos onto physical cafe walls, cups, or office doors.
- Legal & Permissions: All photography must have signed commercial model releases. Reference imagery must be replaced with cleared production assets before publication.

---

## 2. PHOTO + TEXT COMPOSITION (USE VS AVOID)
- Rule of Space: Subject placed to one side of the frame, leaving generous negative space for messaging.
- Aspect Ratio Standard: 16:9 for landscape marketing/hero headers, 3:2 for editorial galleries.
- Text Legibility & Overlays:
  * Use gentle, localized dark gradient overlays (e.g., 90deg, 0.92 to 0 opacity).
  * Never place body text or critical headlines across high-contrast facial features or patterned clothing.
  * Keep the approved 'peopi.' wordmark with its mandatory clear space.

---

## 3. PURPOSEFUL GRAPHIC LANGUAGE
- Discovery Rings: Concentric orange (#FF3300) rings suggest proximity and potential connection. Never represent exact GPS coordinates, user counts, or real-time density.
- Atmosphere Shapes: Restrained soft warm and neutral shapes (#FDEEE7, #FF3300, #1E293B) provide subtle depth behind copy without visual clutter.
- Connection Motifs: Clean curved connector lines between minimal nodes illustrate mutual reachability without fabricating verified user ties.

---

## 4. PRODUCTION CHECKLIST BEFORE PUBLICATION
1. People & Permissions: Verified model releases and commercial licenses on file.
2. Authenticity: Illustrative imagery is never presented as real user testimonials.
3. Accessibility: Minimum 4.5:1 text contrast ratio; descriptive alt text provided for all visual assets.
`;

function downloadPhotoMotifSvg(motifKey) {
  let svgContent = '';
  let filename = '';
  if (motifKey === 'rings') {
    svgContent = getDiscoveryRingsSvg();
    filename = 'peopi-discovery-rings.svg';
  } else if (motifKey === 'atmosphere') {
    svgContent = getAtmosphereSvg();
    filename = 'peopi-atmosphere.svg';
  } else if (motifKey === 'connection') {
    svgContent = getConnectionMotifSvg();
    filename = 'peopi-connection-motif.svg';
  }
  if (!svgContent) return;

  const blob = new Blob([svgContent], { type: 'image/svg+xml;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  toast(`Downloaded: ${filename}`);
}

function downloadPhotoUsageGuide() {
  const blob = new Blob([PEOPI_PHOTO_EXPORT_GUIDE_MD], { type: 'text/markdown;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'peopi-photography-graphic-guide.md';
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  toast('Downloaded: peopi-photography-graphic-guide.md');
}

function downloadVisualZipKit() {
  try {
    const ringsSvg = getDiscoveryRingsSvg();
    const atmosphereSvg = getAtmosphereSvg();
    const connectionSvg = getConnectionMotifSvg();

    const files = [
      { name: 'README-visual-guidelines.md', content: PEOPI_PHOTO_EXPORT_GUIDE_MD },
      { name: 'graphics/peopi-discovery-rings.svg', content: ringsSvg },
      { name: 'graphics/peopi-atmosphere.svg', content: atmosphereSvg },
      { name: 'graphics/peopi-connection-motif.svg', content: connectionSvg },
      { name: 'PHOTO-RIGHTS-AND-LICENSING.md', content: `# PHOTO RIGHTS & PRODUCTION LICENSING NOTES
Reference imagery currently shown in the Peopi style guide is for illustrative composition guidance only.
Before publishing any materials:
1. Ensure full commercial model releases are on file.
2. Confirm photography has been licensed or cleared for commercial redistribution.
3. Replace all temporary reference assets with cleared final production files.` }
    ];

    const blob = createZipArchive(files);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'peopi-visual-kit.zip';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast('Downloaded: peopi-visual-kit.zip');
  } catch (err) {
    console.error('ZIP download failed', err);
    toast('Download failed. Please try again.');
  }
}

