function initStoreGuideInteractions() {
  // 1. Platform Toggle (App Store vs Google Play)
  const btnIos = $('#ds-content #btn-plat-ios');
  const btnAndroid = $('#ds-content #btn-plat-android');
  const indicators = all('#ds-content .store-plat-indicator');

  if (btnIos && btnAndroid) {
    btnIos.addEventListener('click', () => {
      btnIos.classList.add('active');
      btnIos.setAttribute('aria-pressed', 'true');
      btnAndroid.classList.remove('active');
      btnAndroid.setAttribute('aria-pressed', 'false');
      indicators.forEach(el => { el.textContent = 'iOS 6.7" Display (1290 × 2796)'; });
    });

    btnAndroid.addEventListener('click', () => {
      btnAndroid.classList.add('active');
      btnAndroid.setAttribute('aria-pressed', 'true');
      btnIos.classList.remove('active');
      btnIos.setAttribute('aria-pressed', 'false');
      indicators.forEach(el => { el.textContent = 'Concept — Android capture pending'; });
    });
  }

  // 2. Copy Store Description
  const btnCopyDesc = $('#ds-content #btn-copy-store-desc');
  const descText = $('#ds-content #store-desc-text');
  if (btnCopyDesc && descText) {
    btnCopyDesc.addEventListener('click', () => {
      const text = descText.textContent.trim();
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(() => {
          toast('Copied store description');
        }).catch(() => {
          toast('Unable to copy text');
        });
      }
    });
  }

  // 3. Zoom Lightbox for Screenshots
  const lightbox = $('#ds-content #store-lightbox');
  const lightboxContent = $('#ds-content #store-lightbox-content');
  const lightboxBody = $('#ds-content #store-lightbox-body');
  const closeBtn = $('#ds-content #store-lightbox-close');
  let lastActiveScreenshot = null;

  const screenshotsData = [
    {
      class: 'store-shot-orange',
      title: 'Meet what’s next.',
      sub: '01 / Discover · Verified Prototype',
      imgSrc: 'assets/screens/screen-active-light.png',
      alt: 'Peopi Proximity Discovery Screen'
    },
    {
      class: 'store-shot-light',
      title: 'Connect with intention.',
      sub: '02 / Connect · Verified Prototype',
      imgSrc: 'assets/screens/screen-profile-light.png',
      alt: 'Peopi Profile & Connection Screen'
    },
    {
      class: 'store-shot-dark',
      title: 'Stay in touch.',
      sub: '03 / Keep in touch · Verified Prototype',
      imgSrc: 'assets/screens/screen-conversation-dark.png',
      alt: 'Peopi Direct Messaging Screen'
    }
  ];

  function openStoreLightbox(idx) {
    const data = screenshotsData[idx];
    if (!data || !lightbox || !lightboxBody) return;
    lightboxContent.className = 'store-lightbox-content ' + data.class;
    lightboxBody.innerHTML = `
      <div style="margin-bottom:12px;">
        <h2 style="font-size:clamp(22px,3vw,30px);font-weight:800;margin:0 0 4px;letter-spacing:-0.03em;">${data.title}</h2>
        <span style="font-size:12px;opacity:0.85;font-weight:600;">${data.sub}</span>
      </div>
      <div class="store-lightbox-phone-frame" style="width:78%;max-width:270px;margin:0 auto;border:3px solid rgba(255,255,255,0.25);border-bottom:0;border-radius:24px 24px 0 0;overflow:hidden;box-shadow:0 -4px 24px rgba(0,0,0,0.3);background:#fff;padding:3px 3px 0 3px;">
        <img src="${data.imgSrc}" alt="${data.alt}" style="width:100%;height:auto;display:block;border-radius:20px 20px 0 0;">
      </div>
      <div style="font-size:11.5px;opacity:0.75;text-align:center;margin-top:8px;">Press ESC or tap outside to close</div>
    `;
    lightbox.classList.add('open');
    closeBtn.focus();
    document.addEventListener('keydown', handleStoreLightboxKeydown);
  }

  function closeStoreLightbox() {
    if (!lightbox) return;
    lightbox.classList.remove('open');
    document.removeEventListener('keydown', handleStoreLightboxKeydown);
    if (lastActiveScreenshot) {
      lastActiveScreenshot.focus();
    }
  }

  function handleStoreLightboxKeydown(e) {
    if (e.key === 'Escape') closeStoreLightbox();
  }

  all('#ds-content [data-zoom-store]').forEach(card => {
    card.addEventListener('click', () => {
      lastActiveScreenshot = card;
      const idx = parseInt(card.dataset.zoomStore, 10);
      openStoreLightbox(idx);
    });
    card.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        lastActiveScreenshot = card;
        const idx = parseInt(card.dataset.zoomStore, 10);
        openStoreLightbox(idx);
      }
    });
  });

  if (closeBtn) {
    closeBtn.addEventListener('click', () => closeStoreLightbox());
  }
  if (lightbox) {
    lightbox.addEventListener('click', e => {
      if (e.target === lightbox) closeStoreLightbox();
    });
  }

  // 4. Download Buttons
  const btnIcons = $('#ds-content #btn-store-download-icons');
  const btnScreens = $('#ds-content #btn-store-download-screenshots');
  const btnGuide = $('#ds-content #btn-store-download-guide');
  const btnAll = $('#ds-content #btn-store-download-all');

  if (btnIcons) {
    btnIcons.addEventListener('click', () => {
      const svg = getApprovedAppIconSvg(1024, false);
      const blob = new Blob([svg], { type: 'image/svg+xml;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'peopi-app-icon-1024-master.svg';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      toast('Downloaded: peopi-app-icon-1024-master.svg');
    });
  }

  if (btnScreens) {
    btnScreens.addEventListener('click', () => {
      const svg = getFeatureGraphicSvg();
      const blob = new Blob([svg], { type: 'image/svg+xml;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'peopi-google-play-feature-graphic-1024x500.svg';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      toast('Downloaded: peopi-google-play-feature-graphic-1024x500.svg');
    });
  }

  if (btnGuide) {
    btnGuide.addEventListener('click', () => {
      const blob = new Blob([PEOPI_STORE_EXPORT_GUIDE_MD], { type: 'text/markdown;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'peopi-store-assets-export-guide.md';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      toast('Downloaded: peopi-store-assets-export-guide.md');
    });
  }

  if (btnAll) {
    btnAll.addEventListener('click', () => downloadStoreZipKit());
  }
}



