function downloadSvgFile(svgString, filename) {
  const blob = new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  toast('Downloaded: ' + filename);
}

function downloadSvgAsPng(svgString, filename, targetWidth, targetHeight) {
  const img = new Image();
  const svgBlob = new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' });
  const url = URL.createObjectURL(svgBlob);
  img.onload = () => {
    const canvas = document.createElement('canvas');
    canvas.width = targetWidth;
    canvas.height = targetHeight;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(img, 0, 0, targetWidth, targetHeight);
    canvas.toBlob((blob) => {
      URL.revokeObjectURL(url);
      if (!blob) return;
      const pngUrl = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = pngUrl;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(pngUrl), 1000);
      toast('Downloaded: ' + filename);
    }, 'image/png');
  };
  img.onerror = () => {
    URL.revokeObjectURL(url);
    toast('Image export failed. Please try SVG format.');
  };
  img.src = url;
}

function downloadPressZipKit() {
  try {
    const wmLight = getWordmarkLightSvg();
    const wmDark = getWordmarkDarkSvg();
    const appIcon = getApprovedAppIconSvg(1024, false);
    const screen1 = getPressScreenSvg(0);
    const screen2 = getPressScreenSvg(1);
    const screen3 = getPressScreenSvg(2);

    const descriptionsTxt = `PEOPI PRODUCT DESCRIPTIONS
==================================================

1. ONE-SENTENCE DESCRIPTION (18 words)
${PEOPI_PRESS_DESCRIPTIONS.sentence}

2. SHORT DESCRIPTION (48 words)
${PEOPI_PRESS_DESCRIPTIONS.short}

3. FULL DESCRIPTION (92 words)
${PEOPI_PRESS_DESCRIPTIONS.full}
`;

    const files = [
      { name: 'README-press-kit-guide.md', content: PEOPI_PRESS_README_MD },
      { name: 'peopi-product-descriptions.txt', content: descriptionsTxt },
      { name: 'logos/peopi-wordmark-light-bg.svg', content: wmLight },
      { name: 'logos/peopi-wordmark-dark-bg.svg', content: wmDark },
      { name: 'logos/peopi-app-icon-1024x1024.svg', content: appIcon },
      { name: 'screens/01-discover-prototype.svg', content: screen1 },
      { name: 'screens/02-connections-prototype.svg', content: screen2 },
      { name: 'screens/03-profile-prototype.svg', content: screen3 }
    ];

    const blob = createZipArchive(files);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'peopi-press-pack.zip';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast('Downloaded: peopi-press-pack.zip');
  } catch (err) {
    console.error('Press pack download failed', err);
    toast('Download failed. Please try again.');
  }
}

