function initPressKitInteractions() {
  // 1. Hero copy buttons
  const btnShort = $('#ds-content #btn-copy-short-intro');
  if (btnShort) {
    btnShort.addEventListener('click', () => {
      copyTextWithFeedback(PEOPI_PRESS_DESCRIPTIONS.sentence, btnShort, 'Copied short intro to clipboard');
    });
  }

  const btnFull = $('#ds-content #btn-copy-full-intro');
  if (btnFull) {
    btnFull.addEventListener('click', () => {
      copyTextWithFeedback(PEOPI_PRESS_DESCRIPTIONS.short, btnFull, 'Copied full intro to clipboard');
    });
  }

  // 2. Section 1 copy buttons
  all('#ds-content [data-copy-desc]').forEach(btn => {
    btn.addEventListener('click', () => {
      const type = btn.dataset.copyDesc;
      const text = PEOPI_PRESS_DESCRIPTIONS[type] || PEOPI_PRESS_DESCRIPTIONS.sentence;
      copyTextWithFeedback(text, btn, 'Copied ' + type + ' description to clipboard');
    });
  });

  // 3. Section 2 Asset downloads
  all('#ds-content [data-dl-asset]').forEach(btn => {
    btn.addEventListener('click', () => {
      const asset = btn.dataset.dlAsset;
      const fmt = btn.dataset.format;
      if (asset === 'wm-light') {
        const svg = getWordmarkLightSvg();
        if (fmt === 'svg') downloadSvgFile(svg, 'peopi-wordmark-light-bg.svg');
        else downloadSvgAsPng(svg, 'peopi-wordmark-light-bg.png', 2400, 800);
      } else if (asset === 'wm-dark') {
        const svg = getWordmarkDarkSvg();
        if (fmt === 'svg') downloadSvgFile(svg, 'peopi-wordmark-dark-bg.svg');
        else downloadSvgAsPng(svg, 'peopi-wordmark-dark-bg.png', 2400, 800);
      } else if (asset === 'app-icon') {
        const svg = getApprovedAppIconSvg(1024, false);
        if (fmt === 'svg') downloadSvgFile(svg, 'peopi-app-icon-1024x1024.svg');
        else downloadSvgAsPng(svg, 'peopi-app-icon-1024x1024.png', 1024, 1024);
      }
    });
  });

  // 4. Section 3 Screen Zoom / Lightbox & Downloads
  const lightbox = $('#ds-content #press-lightbox');
  const lightboxContent = $('#ds-content #press-lightbox-content');
  const lightboxTitle = $('#ds-content #press-lightbox-title');
  const lightboxClose = $('#ds-content #press-lightbox-close');
  const lightboxBackdrop = $('#ds-content #press-lightbox-backdrop');
  const lightboxDlBtn = $('#ds-content #press-lightbox-dl-btn');

  let activeScreenIdx = 0;
  const screenTitles = [
    "01 / Discover — Radar & nearby list",
    "02 / Connections — Requests & active peers",
    "03 / Profile — Professional intent & badges"
  ];

  function openScreenLightbox(idx) {
    activeScreenIdx = idx;
    if (lightboxTitle) lightboxTitle.textContent = screenTitles[idx] || "Product Screen";
    if (lightboxContent) {
      const svg = getPressScreenSvg(idx);
      lightboxContent.innerHTML = `<div style="width:100%;max-width:340px;box-shadow:0 12px 36px rgba(0,0,0,0.25);border-radius:24px;overflow:hidden;">${svg}</div>`;
    }
    if (lightbox) lightbox.hidden = false;
  }

  function closeScreenLightbox() {
    if (lightbox) lightbox.hidden = true;
  }

  if (lightboxClose) lightboxClose.addEventListener('click', closeScreenLightbox);
  if (lightboxBackdrop) lightboxBackdrop.addEventListener('click', closeScreenLightbox);
  window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && lightbox && !lightbox.hidden) closeScreenLightbox();
  });

  if (lightboxDlBtn) {
    lightboxDlBtn.addEventListener('click', () => {
      const svg = getPressScreenSvg(activeScreenIdx);
      const names = ['discover', 'connections', 'profile'];
      downloadSvgAsPng(svg, 'peopi-' + names[activeScreenIdx] + '-screen.png', 750, 1334);
    });
  }

  all('#ds-content [data-zoom-screen]').forEach(trigger => {
    trigger.addEventListener('click', () => {
      const idx = parseInt(trigger.dataset.zoomScreen, 10) || 0;
      openScreenLightbox(idx);
    });
  });

  all('#ds-content [data-dl-screen]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const idx = parseInt(btn.dataset.dlScreen, 10) || 0;
      const svg = getPressScreenSvg(idx);
      const names = ['discover', 'connections', 'profile'];
      downloadSvgAsPng(svg, 'peopi-' + names[idx] + '-screen.png', 750, 1334);
    });
  });

  const btnAllScreens = $('#ds-content #btn-dl-all-screens');
  if (btnAllScreens) {
    btnAllScreens.addEventListener('click', () => downloadProductImagesZip());
  }

  // 5. Section 4 Pack buttons
  const btnMedia = $('#ds-content #btn-pack-media');
  if (btnMedia) btnMedia.addEventListener('click', () => downloadPressZipKit());

  const btnPartner = $('#ds-content #btn-pack-partner');
  if (btnPartner) btnPartner.addEventListener('click', () => downloadPartnerZipKit());
}



