// WCAG relative luminance math
function calculateLuminance(hex) {
  const cleanHex = hex.replace('#', '');
  const r = parseInt(cleanHex.substring(0, 2), 16) / 255;
  const g = parseInt(cleanHex.substring(2, 4), 16) / 255;
  const b = parseInt(cleanHex.substring(4, 6), 16) / 255;
  const [R, G, B] = [r, g, b].map(v => v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4));
  return 0.2126 * R + 0.7152 * G + 0.0722 * B;
}

function calculateContrastRatio(hex1, hex2) {
  const l1 = calculateLuminance(hex1);
  const l2 = calculateLuminance(hex2);
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}

function downloadPatternsZipKit() {
  try {
    const discoverySvg = getDiscoveryPatternSvg();
    const connectionSvg = getConnectionPatternSvg();
    const presenceSvg = getPresencePatternSvg();

    const readme = `# Peopi Proposed Pattern System
Version: 1.0 (Brand Applications)

## 01 / Discovery
Signals opportunity, curiosity and what's next. Concentric orange rings radiating outward from the focal anchor.

## 02 / Connection
Represents people, movement and a more open network. Interconnecting light curves on ink background with Peopi orange connection nodes.

## 03 / Presence
A bold and distinctive rhythmic Bauhaus expression. Geometric modules of quarter circles and solid squares in #FF3300, #141922 and #FFFFFF.

## Usage Guidelines:
- Use behind short brand messages, presentations, event banners and campaigns.
- Never use behind dense, data-rich product interfaces.
- Keep all colors mapped strictly to the approved Peopi palette.
`;

    const files = [
      { name: 'README-pattern-guide.md', content: readme },
      { name: 'patterns/01-peopi-discovery-pattern.svg', content: discoverySvg },
      { name: 'patterns/02-peopi-connection-pattern.svg', content: connectionSvg },
      { name: 'patterns/03-peopi-presence-pattern.svg', content: presenceSvg }
    ];

    const blob = createZipArchive(files);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'peopi-patterns.zip';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast('Downloaded: peopi-patterns.zip');
  } catch (err) {
    console.error('Pattern ZIP download failed', err);
    toast('Download failed. Please try again.');
  }
}

let dsToastTimer = null;
function dsToast(message, iconName = 'check') {
  let toastEl = document.getElementById('ds-toast');
  if (!toastEl) {
    toastEl = document.createElement('div');
    toastEl.id = 'ds-toast';
    toastEl.className = 'ds-toast';
    toastEl.setAttribute('role', 'status');
    toastEl.setAttribute('aria-live', 'polite');
    const ws = document.getElementById('ds-workspace') || document.body;
    ws.appendChild(toastEl);
  }
  clearTimeout(dsToastTimer);
  toastEl.innerHTML = '<i class="ph ph-' + iconName + '" aria-hidden="true"></i><span>' + message + '</span>';
  toastEl.classList.add('show');
  dsToastTimer = setTimeout(() => {
    toastEl.classList.remove('show');
  }, 2200);
}

function copyTextWithFeedback(text, btnElement, successMessage) {
  const isDsActive = !document.getElementById('ds-workspace')?.hidden;
  const notify = (msg) => {
    if (isDsActive) dsToast(msg);
    else toast(msg);
  };
  const handleSuccess = () => {
    notify(successMessage || 'Copied to clipboard');
    if (btnElement) {
      btnElement.classList.add('copied');
      btnElement.classList.add('ds-copied');
      setTimeout(() => {
        btnElement.classList.remove('copied');
        btnElement.classList.remove('ds-copied');
      }, 1500);
    }
  };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      handleSuccess();
    }).catch(err => {
      console.warn('Clipboard write failed:', err);
      fallbackCopyText(text, successMessage, handleSuccess);
    });
  } else {
    fallbackCopyText(text, successMessage, handleSuccess);
  }
}

function fallbackCopyText(text, successMessage, onSuccess) {
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.left = '-9999px';
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    if (onSuccess) onSuccess();
    else if (!document.getElementById('ds-workspace')?.hidden) dsToast(successMessage || 'Copied to clipboard');
    else toast(successMessage || 'Copied to clipboard');
  } catch (e) {
    if (!document.getElementById('ds-workspace')?.hidden) dsToast('Copy failed. Please copy manually.', 'warning');
    else toast('Copy failed. Please copy manually.');
  }
}

function initColorGuideInteractions() {

  // 2. Swatch Click-to-copy
  all('#ds-content [data-copy-hex]').forEach(el => {
    if (!el.getAttribute('tabindex')) el.setAttribute('tabindex', '0');
    if (!el.getAttribute('role')) el.setAttribute('role', 'button');
    const doCopy = () => {
      const hex = el.getAttribute('data-copy-hex');
      if (!hex) return;
      copyTextWithFeedback(hex, el, 'Copied ' + hex + ' to clipboard');
    };
    el.addEventListener('click', doCopy);
    el.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        doCopy();
      }
    });
  });

  // 3. Pattern Download Buttons
  all('#ds-content [data-dl-pattern]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const pat = btn.getAttribute('data-dl-pattern');
      let svg = '';
      let filename = 'peopi-pattern.svg';
      if (pat === 'discovery') {
        svg = getDiscoveryPatternSvg();
        filename = '01-peopi-discovery-pattern.svg';
      } else if (pat === 'connection') {
        svg = getConnectionPatternSvg();
        filename = '02-peopi-connection-pattern.svg';
      } else if (pat === 'presence') {
        svg = getPresencePatternSvg();
        filename = '03-peopi-presence-pattern.svg';
      }
      if (svg) downloadSvgFile(svg, filename);
    });
  });

  // 4. Contrast Inspector Module
  let activeFg = '#141922';
  let activeBg = '#FFFFFF';

  const ratioNumEl = document.getElementById('color-ratio-num');
  const previewStage = document.getElementById('color-contrast-preview-stage');
  const badgeNormal = document.getElementById('color-badge-normal');
  const badgeLarge = document.getElementById('color-badge-large');
  const explanationEl = document.getElementById('color-contrast-explanation');

  function updateContrastCalculation() {
    const ratio = calculateContrastRatio(activeFg, activeBg);
    const roundedRatio = (Math.round(ratio * 100) / 100).toFixed(2);
    if (ratioNumEl) ratioNumEl.textContent = roundedRatio + ' : 1';

    if (previewStage) {
      previewStage.style.backgroundColor = activeBg;
      previewStage.style.color = activeFg;
    }

    // Normal Text (<18pt / <14pt bold): AA requires 4.5, AAA requires 7.0
    const passNormalAA = ratio >= 4.5;
    const passNormalAAA = ratio >= 7.0;
    if (badgeNormal) {
      badgeNormal.className = 'color-badge-wcag ' + (passNormalAA ? 'pass' : 'fail');
      badgeNormal.textContent = passNormalAAA ? 'Normal: PASS AAA' : (passNormalAA ? 'Normal: PASS AA' : 'Normal: FAIL');
    }

    // Large Text (>=18pt or bold >=14pt): AA requires 3.0, AAA requires 4.5
    const passLargeAA = ratio >= 3.0;
    const passLargeAAA = ratio >= 4.5;
    if (badgeLarge) {
      badgeLarge.className = 'color-badge-wcag ' + (passLargeAA ? 'pass' : 'fail');
      badgeLarge.textContent = passLargeAAA ? 'Large: PASS AAA' : (passLargeAA ? 'Large: PASS AA' : 'Large: FAIL');
    }

    if (explanationEl) {
      if (activeFg === '#FFFFFF' && activeBg === '#FF3300') {
        explanationEl.textContent = 'Note: White text on #FF3300 achieves 3.69:1 contrast. It passes WCAG AA for Large Text (>=18pt or bold >=14pt such as buttons and hero labels), but should not be used for dense body copy.';
      } else if (ratio < 4.5) {
        explanationEl.textContent = 'Contrast ratio (' + roundedRatio + ':1) is below 4.5:1. Avoid using this pairing for essential body text or form inputs.';
      } else {
        explanationEl.textContent = 'WCAG compliant pairing (' + roundedRatio + ':1). Safe for production UI readability.';
      }
    }
  }

  // Presets
  all('#ds-content .color-contrast-preset-chip').forEach(chip => {
    chip.addEventListener('click', () => {
      all('#ds-content .color-contrast-preset-chip').forEach(c => c.classList.remove('active'));
      chip.classList.add('active');
      activeFg = chip.getAttribute('data-fg') || '#141922';
      activeBg = chip.getAttribute('data-bg') || '#FFFFFF';

      // update swatch button active classes
      all('#ds-content [data-pick-fg]').forEach(b => b.classList.toggle('active', b.getAttribute('data-pick-fg') === activeFg));
      all('#ds-content [data-pick-bg]').forEach(b => b.classList.toggle('active', b.getAttribute('data-pick-bg') === activeBg));

      updateContrastCalculation();
    });
  });

  // FG Swatch pickers
  all('#ds-content [data-pick-fg]').forEach(btn => {
    btn.addEventListener('click', () => {
      all('#ds-content [data-pick-fg]').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      activeFg = btn.getAttribute('data-pick-fg');
      all('#ds-content .color-contrast-preset-chip').forEach(c => c.classList.remove('active'));
      updateContrastCalculation();
    });
  });

  // BG Swatch pickers
  all('#ds-content [data-pick-bg]').forEach(btn => {
    btn.addEventListener('click', () => {
      all('#ds-content [data-pick-bg]').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      activeBg = btn.getAttribute('data-pick-bg');
      all('#ds-content .color-contrast-preset-chip').forEach(c => c.classList.remove('active'));
      updateContrastCalculation();
    });
  });

  updateContrastCalculation();

  // 5. Export Actions
  const btnCopyCss = document.getElementById('color-btn-copy-css');
  if (btnCopyCss) {
    btnCopyCss.addEventListener('click', () => {
      copyTextWithFeedback(PEOPI_CSS_TOKENS, btnCopyCss, 'Copied CSS tokens to clipboard');
    });
  }

  const btnDlTokens = document.getElementById('color-btn-dl-tokens');
  if (btnDlTokens) {
    btnDlTokens.addEventListener('click', () => {
      const blob = new Blob([PEOPI_COLOR_TOKENS_JSON], { type: 'application/json;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'peopi-tokens.json';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      toast('Downloaded: peopi-tokens.json');
    });
  }

  const btnDlPatternsZip = document.getElementById('color-btn-dl-patterns');
  if (btnDlPatternsZip) {
    btnDlPatternsZip.addEventListener('click', () => {
      downloadPatternsZipKit();
    });
  }
}



