function initFoundationInteractions() {
  // Toggle Measurements
  const btnToggle = document.getElementById('btn-toggle-measurements');
  const annotWrap = document.getElementById('annotated-component-wrap');
  if (btnToggle && annotWrap) {
    const isInitiallyShown = annotWrap.classList.contains('show-measurements');
    btnToggle.classList.toggle('active', isInitiallyShown);
    btnToggle.setAttribute('aria-pressed', String(isInitiallyShown));
    const span = btnToggle.querySelector('span');
    if (span) span.textContent = isInitiallyShown ? 'Hide measurements' : 'Show measurements';

    btnToggle.addEventListener('click', () => {
      const isActive = annotWrap.classList.toggle('show-measurements');
      btnToggle.classList.toggle('active', isActive);
      btnToggle.setAttribute('aria-pressed', String(isActive));
      const textSpan = btnToggle.querySelector('span');
      if (textSpan) textSpan.textContent = isActive ? 'Hide measurements' : 'Show measurements';
      toast(isActive ? 'Measurement lines visible' : 'Measurement lines hidden');
      if (isActive) updateAnnotatedSpacingMeasurements();
    });
  }

  // Dynamic sub-pixel alignment of 8px icon gap annotation
  function updateAnnotatedSpacingMeasurements() {
    const card = document.querySelector('.annotated-card');
    const avatar = card ? card.querySelector('.annotated-avatar') : null;
    const meta = card ? card.querySelector('.annotated-meta') : null;
    const badge = card ? card.querySelector('.icon-gap-badge') : null;
    const topBadge = card ? card.querySelector('.top-pad-badge') : null;
    const botBadge = card ? card.querySelector('.bottom-pad-badge') : null;
    const contentBadge = card ? card.querySelector('.content-gap-badge') : null;
    const svg = card ? card.querySelector('.annotated-spacing-svg') : null;
    if (!card || !avatar || !meta || !svg) return;

    const cardRect = card.getBoundingClientRect();
    const avatarRect = avatar.getBoundingClientRect();
    const metaRect = meta.getBoundingClientRect();

    const x1 = avatarRect.right - cardRect.left;
    const x2 = metaRect.left - cardRect.left;
    const xCenter = (x1 + x2) / 2;

    const tickTop = avatarRect.top - cardRect.top - 6;
    const tickBottom = tickTop + 14;
    const barY = tickTop + 7;

    const isMobile = window.innerWidth <= 640;

    let mobileSvgGroup = svg.querySelector('.annotated-svg-mobile-connectors');
    if (!mobileSvgGroup) {
      mobileSvgGroup = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      mobileSvgGroup.setAttribute('class', 'annotated-svg-mobile-connectors');
      svg.appendChild(mobileSvgGroup);
    }

    const tickLeft = svg.querySelector('.tick-left');
    const tickRight = svg.querySelector('.tick-right');
    const tickBar = svg.querySelector('.tick-bar');
    const leaderRoute = svg.querySelector('.leader-route');

    if (tickLeft) {
      tickLeft.setAttribute('x1', x1);
      tickLeft.setAttribute('y1', tickTop);
      tickLeft.setAttribute('x2', x1);
      tickLeft.setAttribute('y2', tickBottom);
    }
    if (tickRight) {
      tickRight.setAttribute('x1', x2);
      tickRight.setAttribute('y1', tickTop);
      tickRight.setAttribute('x2', x2);
      tickRight.setAttribute('y2', tickBottom);
    }
    if (tickBar) {
      tickBar.setAttribute('x1', x1);
      tickBar.setAttribute('y1', barY);
      tickBar.setAttribute('x2', x2);
      tickBar.setAttribute('y2', barY);
    }

    if (isMobile) {
      // Mobile: straight vertical leader from 8px gap up to icon-gap-badge
      if (leaderRoute) {
        leaderRoute.setAttribute('d', `M ${xCenter} ${barY} L ${xCenter} -14`);
      }

      const cardH = cardRect.height;
      const topPadRect = topBadge ? topBadge.getBoundingClientRect() : null;
      const botPadRect = botBadge ? botBadge.getBoundingClientRect() : null;
      const contentRect = contentBadge ? contentBadge.getBoundingClientRect() : null;

      const topPadCenterX = topPadRect ? (topPadRect.left + topPadRect.width / 2 - cardRect.left) : (cardRect.width - 55);
      const botPadCenterX = botPadRect ? (botPadRect.left + botPadRect.width / 2 - cardRect.left) : (cardRect.width - 55);
      const leftChannelX = 12;

      mobileSvgGroup.innerHTML = `
        <!-- Top Pad vertical leader with horizontal tick in top 24px zone -->
        <line x1="${topPadCenterX}" y1="-14" x2="${topPadCenterX}" y2="12" stroke="#FF3300" stroke-width="1" stroke-dasharray="3 2.5"/>
        <line x1="${topPadCenterX - 8}" y1="12" x2="${topPadCenterX + 8}" y2="12" stroke="#FF3300" stroke-width="1.5"/>

        <!-- Bottom Pad vertical leader with horizontal tick in bottom 24px zone -->
        <line x1="${botPadCenterX}" y1="${cardH - 12}" x2="${botPadCenterX}" y2="${cardH + 14}" stroke="#FF3300" stroke-width="1" stroke-dasharray="3 2.5"/>
        <line x1="${botPadCenterX - 8}" y1="${cardH - 12}" x2="${botPadCenterX + 8}" y2="${cardH - 12}" stroke="#FF3300" stroke-width="1.5"/>

        <!-- Content Gap 16px bracket in left channel (x=12), routed cleanly down outside bio and button to badge -->
        <line x1="${leftChannelX - 4}" y1="68" x2="${leftChannelX + 4}" y2="68" stroke="#FF3300" stroke-width="1.5"/>
        <line x1="${leftChannelX - 4}" y1="84" x2="${leftChannelX + 4}" y2="84" stroke="#FF3300" stroke-width="1.5"/>
        <line x1="${leftChannelX}" y1="68" x2="${leftChannelX}" y2="84" stroke="#FF3300" stroke-width="1.5"/>
        <line x1="${leftChannelX}" y1="84" x2="${leftChannelX}" y2="${cardH + 14}" stroke="#FF3300" stroke-width="1" stroke-dasharray="3 2.5"/>
        <line x1="${leftChannelX}" y1="${cardH + 14}" x2="${contentRect ? contentRect.left - cardRect.left : 52}" y2="${cardH + 14}" stroke="#FF3300" stroke-width="1" stroke-dasharray="3 2.5"/>
      `;
    } else {
      // Desktop & Tablet (>640px): preserved right-side gutter leader routing
      mobileSvgGroup.innerHTML = '';
      const routeY = 8;
      const badgeRect = badge ? badge.getBoundingClientRect() : null;
      const badgeY = badgeRect ? badgeRect.top + badgeRect.height / 2 - cardRect.top : 46;
      const cardRight = cardRect.width;
      const channelX = cardRight - 10;
      const badgeLeft = badgeRect ? badgeRect.left - cardRect.left : cardRight + 24;

      if (leaderRoute) {
        leaderRoute.setAttribute('d', `M ${xCenter} ${barY} L ${xCenter} ${routeY} L ${channelX} ${routeY} L ${channelX} ${badgeY} L ${badgeLeft} ${badgeY}`);
      }
    }
  }

  updateAnnotatedSpacingMeasurements();
  if (window.ResizeObserver) {
    const card = document.querySelector('.annotated-card');
    if (card && !card._roWired) {
      card._roWired = true;
      const ro = new ResizeObserver(() => updateAnnotatedSpacingMeasurements());
      ro.observe(card);
    }
  }
  if (!window._spacingResizeWired) {
    window._spacingResizeWired = true;
    window.addEventListener('resize', updateAnnotatedSpacingMeasurements);
  }

  const setupKeyCopy = (el, doCopy) => {
    if (!el.getAttribute('tabindex')) el.setAttribute('tabindex', '0');
    if (!el.getAttribute('role')) el.setAttribute('role', 'button');
    el.addEventListener('click', doCopy);
    el.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        doCopy();
      }
    });
  };

  // Click to copy spacing bars
  all('#ds-content [data-copy-spacing]').forEach(el => {
    const val = el.getAttribute('data-copy-spacing');
    if (!val) return;
    setupKeyCopy(el, () => copyTextWithFeedback(val, el, 'Copied ' + val + ' to clipboard'));
  });

  // Click to copy radius cards
  all('#ds-content [data-copy-radius]').forEach(el => {
    const val = el.getAttribute('data-copy-radius');
    if (!val) return;
    setupKeyCopy(el, () => copyTextWithFeedback(val, el, 'Copied radius ' + val + ' to clipboard'));
  });

  // Click to copy shadow cards
  all('#ds-content [data-copy-shadow]').forEach(el => {
    const val = el.getAttribute('data-copy-shadow');
    if (!val) return;
    setupKeyCopy(el, () => copyTextWithFeedback(val, el, 'Copied shadow CSS to clipboard'));
  });

  // Click to copy quick token code rows
  all('#ds-content [data-copy-token]').forEach(el => {
    const val = el.getAttribute('data-copy-token');
    if (!val) return;
    setupKeyCopy(el, () => copyTextWithFeedback(val, el, 'Copied token definition to clipboard'));
  });

  // Copy CSS button
  const btnCopyCss = document.getElementById('btn-copy-foundation-css');
  if (btnCopyCss) {
    btnCopyCss.addEventListener('click', () => {
      copyTextWithFeedback(PEOPI_FOUNDATION_CSS, btnCopyCss, 'Copied all Foundation CSS tokens to clipboard');
    });
  }

  // Download JSON button
  const btnDlJson = document.getElementById('btn-dl-foundation-json');
  if (btnDlJson) {
    btnDlJson.addEventListener('click', () => {
      const blob = new Blob([PEOPI_FOUNDATION_JSON], { type: 'application/json;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'peopi-foundations.json';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      toast('Downloaded: peopi-foundations.json');
    });
  }
}


