// Canonical peopiHandoffData is declared at top level scope for global and Screen handoff accessibility

// Phase 04: Mobile AI Handoff & Selection Motion Engine
async function copyToClipboard(text) {
  let copied = false;
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(text);
      copied = true;
    }
  } catch (e) {
    copied = false;
  }
  if (!copied) {
    try {
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.style.position = 'fixed';
      ta.style.left = '-9999px';
      ta.style.top = '0';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.focus();
      ta.select();
      copied = document.execCommand('copy');
      ta.remove();
    } catch (e) {
      copied = false;
    }
  }
  return copied;
}

const MOTION_EASING = 'cubic-bezier(0.2, 0.8, 0.2, 1)';
const MOTION_DURATION = 260;
const REDUCED_MOTION_DURATION = 120;

function animateSelectionCapsule(container, indicator, targetBtn, options = {}) {
  if (!container || !indicator || !targetBtn) return;
  const isReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const animate = options.animate !== false && !options.instant;

  const targetX = targetBtn.offsetLeft;
  const targetWidth = targetBtn.offsetWidth;

  if (!animate) {
    if (indicator._runningAnimation) {
      indicator._runningAnimation.cancel();
      indicator._runningAnimation = null;
    }
    indicator.style.width = targetWidth + 'px';
    indicator.style.transform = 'translateX(' + targetX + 'px)';
    indicator.style.opacity = '1';
    return;
  }

  if (isReduced) {
    if (indicator._runningAnimation) {
      indicator._runningAnimation.cancel();
      indicator._runningAnimation = null;
    }
    indicator.style.width = targetWidth + 'px';
    indicator.style.transform = 'translateX(' + targetX + 'px)';
    indicator._runningAnimation = indicator.animate([
      { opacity: 0 },
      { opacity: 1 }
    ], {
      duration: REDUCED_MOTION_DURATION,
      easing: 'ease-out',
      fill: 'forwards'
    });
    return;
  }

  // Continuous Retargeting from intermediate matrix position
  let startX = targetX;
  let startWidth = targetWidth;

  const style = window.getComputedStyle(indicator);
  const matrix = style.transform;
  if (matrix && matrix !== 'none') {
    const values = matrix.split('(')[1].split(')')[0].split(',');
    if (values.length >= 6) {
      startX = parseFloat(values[4]);
    }
  } else if (indicator.offsetLeft) {
    startX = indicator.offsetLeft;
  }
  startWidth = parseFloat(style.width) || indicator.offsetWidth || targetWidth;

  if (indicator._runningAnimation) {
    indicator._runningAnimation.cancel();
    indicator._runningAnimation = null;
  }

  indicator.style.width = targetWidth + 'px';
  indicator.style.transform = 'translateX(' + targetX + 'px)';

  indicator._runningAnimation = indicator.animate([
    { transform: 'translateX(' + startX + 'px)', width: startWidth + 'px' },
    { transform: 'translateX(' + targetX + 'px)', width: targetWidth + 'px' }
  ], {
    duration: MOTION_DURATION,
    easing: MOTION_EASING,
    fill: 'both'
  });

  indicator._runningAnimation.onfinish = () => {
    indicator.style.width = targetWidth + 'px';
    indicator.style.transform = 'translateX(' + targetX + 'px)';
    indicator._runningAnimation = null;
  };
}

function cleanEmptyAttrs(el) {
  if (!el) return;
  if (el.hasAttribute('style') && !el.getAttribute('style')) el.removeAttribute('style');
  if (el.hasAttribute('class') && !el.getAttribute('class')) el.removeAttribute('class');
}

function normalizeElementClasses(el) {
  if (!el) return;
  if (!el.className || el.classList.length === 0) {
    el.removeAttribute('class');
    return;
  }
  if (el.classList.length > 1) {
    el.className = Array.from(el.classList).sort().join(' ');
  }
}

function setWorkbenchVariantActive(card, target) {
  if (!card) return;
  const vBtns = card.querySelectorAll('.ds-variant-btn');
  vBtns.forEach((b, i) => {
    const isTarget = (typeof target === 'number') ? (i === target) : (b === target);
    b.classList.remove('active', 'is-active');
    if (isTarget) {
      b.classList.add('active', 'is-active');
    }
  });
}

function selectBottomNav(nav, targetIndexOrBtn, options = {}) {
  if (!nav) return;
  const buttons = Array.from(nav.querySelectorAll('button'));
  if (!buttons.length) return;
  let targetBtn = (typeof targetIndexOrBtn === 'number') ? buttons[targetIndexOrBtn] : targetIndexOrBtn;
  if (!targetBtn || !buttons.includes(targetBtn)) targetBtn = buttons[0];
  const targetIdx = buttons.indexOf(targetBtn);

  buttons.forEach((b, i) => {
    const isTarget = (i === targetIdx);
    b.classList.toggle('current', isTarget);
    if (isTarget) {
      b.setAttribute('aria-current', 'page');
    } else {
      b.removeAttribute('aria-current');
    }
    normalizeElementClasses(b);
  });

  let pill = nav.querySelector('.motion-nav-indicator');
  if (!pill) {
    pill = document.createElement('span');
    pill.className = 'motion-nav-indicator';
    pill.setAttribute('aria-hidden', 'true');
    nav.prepend(pill);
  }

  animateSelectionCapsule(nav, pill, targetBtn, options);

  const card = nav.closest('.ds-workbench-card');
  if (card && options.syncVariant !== false) {
    setWorkbenchVariantActive(card, targetIdx);
    updateCardHandoff(card);
  }
}

function selectSegmented(seg, targetIndexOrBtn, options = {}) {
  if (!seg) return;
  const buttons = Array.from(seg.querySelectorAll('button'));
  if (!buttons.length) return;
  let targetBtn = (typeof targetIndexOrBtn === 'number') ? buttons[targetIndexOrBtn] : targetIndexOrBtn;
  if (!targetBtn || !buttons.includes(targetBtn)) targetBtn = buttons[0];
  const targetIdx = buttons.indexOf(targetBtn);

  buttons.forEach((b, i) => {
    const isTarget = (i === targetIdx);
    b.classList.toggle('chosen', isTarget);
    b.classList.toggle('selected', isTarget);
    b.setAttribute('aria-selected', String(isTarget));
    normalizeElementClasses(b);
  });

  let pill = seg.querySelector('.motion-seg-indicator');
  if (!pill) {
    pill = document.createElement('span');
    pill.className = 'motion-seg-indicator';
    pill.setAttribute('aria-hidden', 'true');
    seg.prepend(pill);
  }

  animateSelectionCapsule(seg, pill, targetBtn, options);

  const card = seg.closest('.ds-workbench-card');
  if (card && options.syncVariant !== false) {
    setWorkbenchVariantActive(card, targetIdx);
    updateCardHandoff(card);
  }
}

// Canonical generateAiBrief is declared at top level scope for global and Screen handoff accessibility
function normalizeHtmlForReference(rawHtml) {
  if (!rawHtml) return '';
  let clean = rawHtml
    .replace(/<p class="ds-specimen-feedback"[^>]*>.*?<\/p>/gi, '')
    .replace(/\s*data-ds-source-id="[^"]*"/g, '')
    .replace(/\s*data-original-[a-z-]+="[^"]*"/g, '')
    .replace(/\b(ds-source-piece|ds-source-root|ds-live-specimen|ds-full-screen)\b/g, '')
    .trim();

  // Merge id="ds-specimen-([^"]+)" safely into existing class attribute or add new class
  clean = clean.replace(/<([a-zA-Z0-9-]+)([^>]*)>/g, (match, tag, attrs) => {
    const idMatch = attrs.match(/\bid="ds-specimen-([^"]+)"/);
    if (!idMatch) return match;
    const specClass = 'peopi-' + idMatch[1];
    let newAttrs = attrs.replace(/\bid="ds-specimen-[^"]*"/, '').trim();
    if (newAttrs.includes('class="')) {
      newAttrs = newAttrs.replace(/class="([^"]*)"/, (m, existingClasses) => {
        const clsList = existingClasses.split(/\s+/).filter(Boolean);
        if (!clsList.includes(specClass)) clsList.push(specClass);
        return 'class="' + clsList.join(' ') + '"';
      });
    } else {
      newAttrs = 'class="' + specClass + '" ' + newAttrs;
    }
    return '<' + tag + ' ' + newAttrs.trim() + '>';
  });

  // Strip workbench phone container wrapper if wrapping the specimen root
  clean = clean.replace(/^\s*<div class="[^"]*\bphone\b[^"]*">\s*([\s\S]*?)\s*<\/div>\s*$/i, '$1').trim();

  clean = clean
    .replace(/\s+class="\s*"/g, '')
    .replace(/class="\s+/g, 'class="')
    .replace(/\s+"/g, '"')
    .replace(/>\s*</g, '>\n<')
    .trim();

  const lines = clean.split('\n').map(l => l.trim()).filter(Boolean);
  let indent = 0;
  const formatted = [];
  for (const line of lines) {
    if (line.match(/^<\/|\/>$/)) indent = Math.max(0, indent - 1);
    formatted.push('  '.repeat(indent) + line);
    if (line.match(/^<[^\/!][^>]*[^/]>$/) && !line.match(/<(input|img|br|hr)/)) {
      indent++;
    }
  }
  return formatted.length ? formatted.join('\n') : clean;
}

