  if(kind==='bc-preview')return ['<svg xmlns="http://www.w3.org/2000/svg" width="1760" height="1860" viewBox="0 0 1760 1860"><defs><style>@import url("https://fonts.googleapis.com/css2?family=Manrope:wght@500;600;700;800&amp;display=swap");text{font-family:"Manrope",system-ui,sans-serif;}</style></defs><rect width="100%" height="100%" fill="#F8FAFC"/><text x="880" y="80" text-anchor="middle" fill="#141922" font-size="44" font-weight="800">Peopi Business Cards · Standard 85 × 55 mm</text><g transform="translate(0,60)"><use href="#sig"/></g></svg>','image/svg+xml'];
