 $('#ds-content').innerHTML=content[key] || '<div class="ds-empty-content" style="padding:48px 24px;text-align:center;color:#64748B;"><p style="font-size:15px;margin:0;">Content coming soon.</p></div>';
 all('#ds-content form').forEach(f=>{
  f.setAttribute('onsubmit','return false;');
  f.addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();return false;});
 });
 all('#ds-content form button:not([type])').forEach(b=>{b.type='button';});
 all('#ds-content form button[type="submit"]').forEach(b=>{
  b.type='button';
  b.addEventListener('click',e=>{
   e.preventDefault();
   const fb=b.closest('.ds-live-specimen')?.querySelector('.ds-specimen-feedback');
   if(fb){
    fb.hidden=false;
    fb.textContent='Message sent (specimen preview).';
    setTimeout(()=>{fb.textContent='';fb.hidden=true;},2500);
   }
  });
 });
 all('#ds-content .ds-icon-tile').forEach(tile=>{
  tile.style.cursor='pointer';
  if(!tile.getAttribute('tabindex'))tile.setAttribute('tabindex','0');
  if(!tile.getAttribute('role'))tile.setAttribute('role','button');
  const iconName=tile.getAttribute('title')||tile.querySelector('span')?.textContent?.trim();
  if(iconName){
   tile.setAttribute('aria-label','Copy icon '+iconName);
   const doCopy=()=>copyTextWithFeedback(iconName,tile,'Copied icon: '+iconName);
   tile.addEventListener('click',doCopy);
   tile.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();doCopy();}});
  }
 });
 all('#ds-content [data-export]').forEach(button=>button.addEventListener('click',()=>{
  if(button.dataset.export==='logo-png-package'){
   const canvas=document.createElement('canvas');
   canvas.width=1024;canvas.height=1024;
   const ctx=canvas.getContext('2d');
   const r=228;
   ctx.fillStyle='#FF3300';
   if(ctx.roundRect){
     ctx.beginPath();ctx.roundRect(0,0,1024,1024,r);ctx.fill();
   }else{
     ctx.beginPath();
     ctx.moveTo(r,0);ctx.lineTo(1024-r,0);ctx.quadraticCurveTo(1024,0,1024,r);
     ctx.lineTo(1024,1024-r);ctx.quadraticCurveTo(1024,1024,1024-r,1024);
     ctx.lineTo(r,1024);ctx.quadraticCurveTo(0,1024,0,1024-r);
     ctx.lineTo(0,r);ctx.quadraticCurveTo(0,0,r,0);
     ctx.closePath();ctx.fill();
   }
   ctx.font='800 560px Manrope, system-ui, sans-serif';
   ctx.textAlign='center';
   ctx.textBaseline='middle';
   ctx.fillStyle='#FFFFFF';
   ctx.fillText('p.',512,545);
   canvas.toBlob(blob=>{
     if(!blob)return;
     const url=URL.createObjectURL(blob);
     const a=document.createElement('a');a.href=url;a.download=button.dataset.file||'peopi-app-symbol.png';
     document.body.appendChild(a);a.click();a.remove();
     setTimeout(()=>URL.revokeObjectURL(url),1000);
     dsToast('Downloaded: '+(button.dataset.file||'peopi-app-symbol.png'),'download-simple');
   },'image/png');
   return;
  }
  const result=asset(button.dataset.export);if(!result)return;
  const url=URL.createObjectURL(new Blob([result[0]],{type:result[1]+';charset=utf-8'}));
  const anchor=document.createElement('a');anchor.href=url;anchor.download=button.dataset.file;document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
  dsToast('Downloaded: '+(button.dataset.file||'asset'),'download-simple');
 }));


 all('#ds-content .ds-live-specimen').forEach(el=>el.classList.toggle('dark',$('#ds-workspace').classList.contains('ds-dark')));
 all('#ds-content .ds-live-specimen button').forEach(button=>button.addEventListener('click',()=>{
  const stage=button.closest('.ds-live-specimen');
  if(button.matches('.prompt-chip')){
   const note=stage.querySelector('textarea');
   const count=stage.querySelector('.profile-request-count span,[id$="profile-request-note-count"]');
   if(note){
    note.value=button.dataset.prompt||button.textContent.trim();
    if(count)count.textContent=String(note.value.length);
    note.focus();
   }
   return;
  }
  if(button.matches('.profile-request-composer-cancel')){
   const composer=stage.querySelector('.profile-request-composer');
   const reqBtn=stage.querySelector('.profile-sheet-footer button.primary:not(.prompt-chip)');
   if(composer)composer.classList.add('hide');
   if(reqBtn)reqBtn.textContent='Request to connect ↗';
   return;
  }
  if(button.matches('.profile-sheet-footer button.primary:not(.prompt-chip)')){
   const composer=stage.querySelector('.profile-request-composer');
   if(composer&&composer.classList.contains('hide')){
    composer.classList.remove('hide');
    button.textContent='Send Request ↗';
    return;
   }
   if(composer&&!composer.classList.contains('hide')){
    composer.classList.add('hide');
    button.textContent='Request pending ✓';
    const feedback=stage.querySelector('.ds-specimen-feedback');
    if(feedback){feedback.hidden=false;feedback.textContent='Request sent with personal note · demo preview';}
    return;
   }
   if(button.textContent.includes('pending')){
    button.textContent='Request to connect ↗';
    return;
   }
  }
  if(button.matches('.sheetclose')){
   const feedback=stage.querySelector('.ds-specimen-feedback');
   if(feedback){feedback.hidden=false;feedback.textContent='Dismiss profile sheet · close preview';}
   return;
  }
  if(button.closest('.session-alert, .ds-session-alert-wrapper, .verify-panel, [data-component="session-alert"], [data-component="verification-status"], [data-component="toast-notification"]')){
   return;
  }
  if(button.matches('.seg button,.durations button,.option,.nav button,.journey-tabs button')){
   const selector=button.matches('.option')?'.option':'button';
   const active=button.matches('.nav button')?'current':button.matches('.journey-tabs button')?'selected':'chosen';
   button.parentElement.querySelectorAll(selector).forEach(el=>{el.classList.toggle(active,el===button);el.setAttribute('aria-pressed',String(el===button))});
  }else if(button.getAttribute('role')==='switch'){
   const checked=button.getAttribute('aria-checked')!=='true';button.setAttribute('aria-checked',String(checked));button.classList.toggle('off',!checked);
  }else{
   const feedback=stage.querySelector('.ds-specimen-feedback');if(feedback){feedback.hidden=false;feedback.textContent=button.textContent.trim()+' · component preview';}
  }
 }));
 all('#ds-content .ds-live-specimen textarea').forEach(textarea=>{
  textarea.addEventListener('input',()=>{
   const stage=textarea.closest('.ds-live-specimen');
   const count=stage?.querySelector('.profile-request-count span,[id$="profile-request-note-count"]');
   if(count)count.textContent=String(textarea.value.length);
  });
 });
  const activateExclusive=(container,button,selector,attribute)=>{container.querySelectorAll(selector).forEach(el=>{const selected=el===button;el.classList.toggle('active',selected);if(attribute)el.setAttribute(attribute,String(selected))})};
 all('#ds-content .ds-peopi-duration button').forEach(button=>button.addEventListener('click',()=>activateExclusive(button.parentElement,button,'button','aria-pressed')));
 all('#ds-content .ds-segment button').forEach(button=>button.addEventListener('click',()=>activateExclusive(button.parentElement,button,'button','aria-pressed')));
 all('#ds-content .ds-tabs button').forEach(button=>button.addEventListener('click',()=>{activateExclusive(button.parentElement,button,'button','aria-selected');const body=button.parentElement.nextElementSibling;if(body)body.textContent=button.textContent.trim()==='Map'?'Map view · Approximate locations only while I’m Open.':'List view · Professionals discoverable under your privacy settings.'}));
 all('#ds-content .ds-bottom-nav button, #ds-content .ds-rail button').forEach(button=>button.addEventListener('click',()=>{activateExclusive(button.parentElement,button,'button',null);if(button.closest('.ds-peopi-bottom-nav'))button.parentElement.querySelectorAll('button').forEach(b=>b.setAttribute('aria-current',b===button?'page':'false'))}));
 all('#ds-content .ds-range').forEach(input=>input.addEventListener('input',()=>{const output=input.closest('label')?.querySelector('.ds-range-value');if(output)output.textContent=input.value}));
 all('#ds-content .ds-toast-preview button').forEach(button=>button.addEventListener('click',()=>{button.closest('.ds-toast-preview').style.display='none'}));
 all('#ds-content .ds-icon-action, #ds-content .ds-fab').forEach(button=>button.addEventListener('click',()=>{button.classList.toggle('ds-demo-active');button.setAttribute('aria-pressed',String(button.classList.contains('ds-demo-active')))}));
  const updateSpecimenNavPill = (nav, activeBtn) => {
    if (!nav) return;
    selectBottomNav(nav, activeBtn, { animate: false });
  };

  const updateSpecimenSegPill = (seg, activeBtn) => {
    if (!seg) return;
    selectSegmented(seg, activeBtn, { animate: false });
  };

  // Apply canonical workbench variant to card preview, variant buttons, and code box
  function applyWorkbenchVariant(card, btnOrVariant, options = {}) {
    if (!card) return;
    window.applyWorkbenchVariant = applyWorkbenchVariant;
    const vBtns = Array.from(card.querySelectorAll('.ds-variant-btn'));
    let btn = null;
    let variant = '';
    if (typeof btnOrVariant === 'string') {
      variant = btnOrVariant.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
      btn = vBtns.find(b => b.dataset.variant === variant) || vBtns[0];
    } else if (typeof btnOrVariant === 'number') {
      btn = vBtns[btnOrVariant] || vBtns[0];
      variant = btn ? btn.dataset.variant : '';
    } else if (btnOrVariant) {
      btn = btnOrVariant;
      variant = btn.dataset.variant || '';
    }

    if (btn) {
      setWorkbenchVariantActive(card, btn);
    }

    const comp = card.dataset.component;
    const preview = card.querySelector('.ds-workbench-preview-viewport');
    if (!preview) return;

    if (comp === 'primary-action' || comp === 'quiet-action' || comp === 'destructive-action') {
      const actionBtn = preview.querySelector('button');
      if (actionBtn) {
        if (!actionBtn._origText) {
          actionBtn._origText = actionBtn.innerHTML;
        }
        const isDis = variant.includes('disabled');
        actionBtn.disabled = isDis;
        if (isDis) {
          actionBtn.style.opacity = '0.45';
        } else {
          actionBtn.style.removeProperty('opacity');
        }
        if (variant === 'loading') {
          actionBtn.innerHTML = '<i class="ph ph-spinner ds-spin" style="margin-right:6px"></i> Opening session...';
        } else {
          actionBtn.innerHTML = actionBtn._origText;
        }
        if (variant.includes('hover') || variant.includes('danger')) {
          if (comp === 'destructive-action') {
            actionBtn.style.backgroundColor = '#dc2626';
            actionBtn.style.color = '#ffffff';
          } else {
            actionBtn.style.filter = 'brightness(1.15)';
          }
        } else {
          actionBtn.style.removeProperty('filter');
          if (comp === 'destructive-action') {
            actionBtn.style.removeProperty('background-color');
            actionBtn.style.removeProperty('color');
          }
        }
        cleanEmptyAttrs(actionBtn);
      }
    } else if (comp === 'icon-button' || comp === 'fab') {
      const iconBtn = preview.querySelector('button');
      if (iconBtn) {
        if (variant.includes('active') || variant.includes('elevated') || variant.includes('raised')) {
          iconBtn.classList.add('ds-demo-active');
          iconBtn.style.transform = 'scale(1.08)';
          iconBtn.style.boxShadow = '0 6px 18px rgba(255,51,0,0.3)';
        } else {
          iconBtn.classList.remove('ds-demo-active');
          iconBtn.style.removeProperty('transform');
          iconBtn.style.removeProperty('box-shadow');
          cleanEmptyAttrs(iconBtn);
        }
      }
    } else if (comp === 'social-auth') {
      const googleBtn = preview.querySelector('[data-ds-source-id="auth-google"], #auth-google');
      const appleBtn = preview.querySelector('[data-ds-source-id="auth-apple"], #auth-apple');
      if (googleBtn) {
        if (variant === 'apple-only') {
          googleBtn.style.display = 'none';
        } else {
          googleBtn.style.removeProperty('display');
          cleanEmptyAttrs(googleBtn);
        }
      }
      if (appleBtn) {
        if (variant === 'google-only') {
          appleBtn.style.display = 'none';
        } else {
          appleBtn.style.removeProperty('display');
          cleanEmptyAttrs(appleBtn);
        }
      }
    } else if (comp === 'form-group') {
      const inputs = preview.querySelectorAll('input');
      if (variant.includes('empty')) {
        inputs.forEach(inp => {
          inp.value = '';
          inp.removeAttribute('value');
          inp.style.removeProperty('border-color');
          inp.style.removeProperty('box-shadow');
          cleanEmptyAttrs(inp);
        });
      } else if (variant.includes('filled')) {
        const vals = ['Alex Morgan', 'Senior Product Designer', 'Miami, FL'];
        inputs.forEach((inp, i) => {
          if (vals[i]) {
            inp.value = vals[i];
            inp.setAttribute('value', vals[i]);
          }
          inp.style.removeProperty('border-color');
          inp.style.removeProperty('box-shadow');
          cleanEmptyAttrs(inp);
        });
      } else if (variant.includes('focus') && inputs[0]) {
        if (!options.initial) inputs[0].focus();
        inputs[0].style.borderColor = '#ff3300';
        inputs[0].style.boxShadow = '0 0 0 3px rgba(255,51,0,0.15)';
      }
    } else if (comp === 'text-field') {
      const inp = preview.querySelector('input');
      if (inp) {
        if (variant.includes('filled')) {
          inp.value = 'Alex Morgan';
          inp.setAttribute('value', 'Alex Morgan');
          inp.style.removeProperty('border-color');
          inp.style.removeProperty('box-shadow');
          cleanEmptyAttrs(inp);
        } else if (variant.includes('focus')) {
          if (!options.initial) inp.focus();
          inp.style.borderColor = '#ff3300';
          inp.style.boxShadow = '0 0 0 3px rgba(255,51,0,0.15)';
        } else {
          inp.value = '';
          inp.removeAttribute('value');
          inp.style.removeProperty('border-color');
          inp.style.removeProperty('box-shadow');
          cleanEmptyAttrs(inp);
        }
      }
    } else if (comp === 'search-field') {
      const inp = preview.querySelector('input');
      const clearBtn = preview.querySelector('.network-search-clear, button');
      if (inp) {
        if (variant.includes('filled')) {
          inp.value = 'Product Designer';
          inp.setAttribute('value', 'Product Designer');
          inp.style.removeProperty('border-color');
          cleanEmptyAttrs(inp);
          if (clearBtn) {
            clearBtn.classList.remove('hide');
            clearBtn.style.removeProperty('display');
            cleanEmptyAttrs(clearBtn);
            normalizeElementClasses(clearBtn);
          }
        } else if (variant.includes('focus')) {
          if (!options.initial) inp.focus();
          inp.style.borderColor = '#ff3300';
          if (clearBtn) {
            clearBtn.classList.add('hide');
            clearBtn.style.removeProperty('display');
            cleanEmptyAttrs(clearBtn);
            normalizeElementClasses(clearBtn);
          }
        } else {
          inp.value = '';
          inp.removeAttribute('value');
          inp.style.removeProperty('border-color');
          cleanEmptyAttrs(inp);
          if (clearBtn) {
            clearBtn.classList.add('hide');
            clearBtn.style.removeProperty('display');
            cleanEmptyAttrs(clearBtn);
            normalizeElementClasses(clearBtn);
          }
        }
      }
    } else if (comp === 'radio') {
      const optionsList = preview.querySelectorAll('.option');
      const isSelected = (variant === 'selected');
      optionsList.forEach((opt, idx) => {
        const choose = isSelected && idx === 0;
        opt.classList.toggle('chosen', choose);
        opt.setAttribute('aria-checked', String(choose));
        normalizeElementClasses(opt);
      });
    } else if (comp === 'session-duration') {
      const durBtns = preview.querySelectorAll('.durations button, button');
      durBtns.forEach((b, idx) => {
        let isChosen = false;
        if (variant.includes('30')) isChosen = (idx === 0);
        else if (variant.includes('120')) isChosen = (idx === 2);
        else isChosen = (idx === 1);
        b.classList.toggle('chosen', isChosen);
        b.setAttribute('aria-pressed', String(isChosen));
        normalizeElementClasses(b);
      });
    } else if (comp === 'switch') {
      const sw = preview.querySelector('[role="switch"], .settings-toggle');
      if (sw) {
        const isOff = variant.includes('off') || variant.includes('disabled');
        sw.setAttribute('aria-checked', String(!isOff));
        sw.classList.toggle('off', isOff);
        normalizeElementClasses(sw);
      }
    } else if (comp === 'intent-choice') {
      const choices = preview.querySelectorAll('.journey-choice');
      const isSelected = (variant === 'selected');
      choices.forEach((c, idx) => {
        const choose = isSelected && (idx === 0 || idx === 3);
        c.classList.toggle('selected', choose);
        c.setAttribute('aria-pressed', String(choose));
        normalizeElementClasses(c);
      });
    } else if (comp === 'skills-chip-input') {
      const chipList = preview.querySelector('.skills-chip-list, [class*="chip-list"]');
      const input = preview.querySelector('input');
      const defaultSkills = ['Product Design', 'Figma', 'Design Systems', 'Prototyping'];
      if (variant.includes('empty')) {
        if (chipList) chipList.innerHTML = '';
        if (input) {
          input.value = '';
          input.removeAttribute('value');
          input.placeholder = 'Type a skill and press Enter...';
          input.style.removeProperty('border-color');
          input.style.removeProperty('box-shadow');
          cleanEmptyAttrs(input);
        }
      } else if (variant.includes('focus')) {
        if (chipList && !chipList.children.length) {
          chipList.innerHTML = defaultSkills.map(s => 
            '<span class="skills-chip-item"><span>' + s + '</span><button type="button" aria-label="Remove ' + s + '">×</button></span>'
          ).join('');
        }
        if (input) {
          if (!options.initial) input.focus();
          input.placeholder = 'Type another skill and press Enter...';
          input.style.borderColor = '#ff3300';
          input.style.boxShadow = '0 0 0 3px rgba(255,51,0,0.15)';
        }
      } else {
        // Default (4 Chips)
        if (chipList) {
          chipList.innerHTML = defaultSkills.map(s => 
            '<span class="skills-chip-item"><span>' + s + '</span><button type="button" aria-label="Remove ' + s + '">×</button></span>'
          ).join('');
        }
        if (input) {
          input.value = '';
          input.removeAttribute('value');
          input.placeholder = 'Type a skill and press Enter...';
          input.style.removeProperty('border-color');
          input.style.removeProperty('box-shadow');
          cleanEmptyAttrs(input);
        }
      }
    } else if (comp === 'discovery-filter') {
      const roleSel = preview.querySelector('select[id*="discovery-role"], select:first-of-type');
      if (roleSel) {
        let targetVal = 'all';
        if (variant.includes('engineering')) targetVal = 'engineer';
        else if (variant.includes('design')) targetVal = 'design';
        else if (variant.includes('founders')) targetVal = 'founder';
        roleSel.value = targetVal;
        Array.from(roleSel.options).forEach(opt => {
          if (opt.value === targetVal) opt.setAttribute('selected', '');
          else opt.removeAttribute('selected');
        });
      }
    } else if (comp === 'bottom-nav') {
      const nav = preview.querySelector('.nav');
      let activeIndex = 0;
      if (variant === 'connections-active') activeIndex = 1;
      else if (variant === 'profile-active') activeIndex = 2;
      if (nav) selectBottomNav(nav, activeIndex, { animate: !options.initial && options.animate !== false, syncVariant: false });
    } else if (comp === 'tabs') {
      const seg = preview.querySelector('.seg');
      const isMap = variant.includes('map');
      if (seg) selectSegmented(seg, isMap ? 0 : 1, { animate: !options.initial && options.animate !== false, syncVariant: false });
    } else if (comp === 'request-tabs') {
      let seg = preview.querySelector('.journey-tabs');
      if (seg) {
        let newHtml = '';
        let targetIdx = 0;
        if (variant === 'conversations-all' || variant.includes('conversation')) {
          newHtml = '<div class="journey-tabs messages-tabs" role="tablist" aria-label="Messages Filter"><button type="button" class="selected chosen" data-messages-tab="current" role="tab" aria-selected="true">Conversations</button><button type="button" data-messages-tab="all" role="tab" aria-selected="false">All</button></div>';
          targetIdx = 0;
        } else if (variant === 'all-requests' || (variant.includes('all') && variant.includes('request'))) {
          newHtml = '<div class="journey-tabs activity-tabs" role="tablist" aria-label="Activity Filter"><button type="button" class="selected chosen" data-activity-tab="all" role="tab" aria-selected="true">All</button><button type="button" data-activity-tab="requests" role="tab" aria-selected="false">Requests</button></div>';
          targetIdx = 0;
        } else if (variant === 'all-hidden' || (variant.includes('all') && variant.includes('hidden'))) {
          newHtml = '<div class="journey-tabs hidden-tabs" id="hidden-tabs" role="tablist" aria-label="Hidden Connections Filter"><button type="button" class="selected chosen" data-hidden-tab="all" role="tab" aria-selected="true">All (1)</button><button type="button" data-hidden-tab="hidden" role="tab" aria-selected="false">Hidden (0)</button></div>';
          targetIdx = 0;
        } else if (variant === 'sent-requests' || variant.includes('sent')) {
          newHtml = '<div class="journey-tabs" id="requests-tabs" role="tablist" aria-label="Requests Filter"><button type="button" data-request-tab="received" role="tab" aria-selected="false">Received (1)</button><button type="button" class="selected chosen" data-request-tab="sent" role="tab" aria-selected="true">Sent (0)</button></div>';
          targetIdx = 1;
        } else {
          // received-requests (default)
          newHtml = '<div class="journey-tabs" id="requests-tabs" role="tablist" aria-label="Requests Filter"><button type="button" class="selected chosen" data-request-tab="received" role="tab" aria-selected="true">Received (1)</button><button type="button" data-request-tab="sent" role="tab" aria-selected="false">Sent (0)</button></div>';
          targetIdx = 0;
        }
        const temp = document.createElement('div');
        temp.innerHTML = newHtml;
        const newSeg = temp.firstElementChild;
        seg.replaceWith(newSeg);
        selectSegmented(newSeg, targetIdx, { animate: !options.initial && options.animate !== false, syncVariant: false });

        newSeg.querySelectorAll('button').forEach((b, idx) => {
          b.addEventListener('click', () => {
            selectSegmented(newSeg, idx, { animate: true, syncVariant: false });
            updateCardHandoff(card);
          });
        });
      }
    } else if (comp === 'app-bar') {
      const head = preview.querySelector('.myprofile-head, header');
      if (head) {
        head.style.removeProperty('background');
        head.style.removeProperty('backdrop-filter');
        head.style.removeProperty('box-shadow');
        cleanEmptyAttrs(head);
      }
    } else if (comp === 'profile-card') {
      const isConn = variant.includes('connected');
      card.classList.toggle('is-connected', isConn);
      setProfileCardState(preview, isConn);
    } else if (comp === 'network-row') {
      let row = preview.querySelector('.journey-person');
      if (row) {
        const badgeSvg = '<span class="li-verified-badge" title="LinkedIn connected (demo)" aria-label="LinkedIn connected — demo"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12 0.8 14.5 2.6 17.6 2.4 19 5.2 21.8 6.6 21.6 9.7 23.2 12 21.6 14.3 21.8 17.4 19 18.8 17.6 21.6 14.5 21.4 12 23.2 9.5 21.4 6.4 21.6 5 18.8 2.2 17.4 2.4 14.3 0.8 12 2.4 9.7 2.2 6.6 5 5.2 6.4 2.4 9.5 2.6Z"/><path d="m7.3 12.1 3.1 3.1 6.5-6.6" fill="none" stroke="#fff" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg></span>';

        let newHtml = '';
        if (variant === 'chat-thread' || variant.includes('chat')) {
          newHtml = [
            '<div class="journey-person conversation-clickable-row" role="button" tabindex="0" aria-label="Open conversation with Alex Morgan">',
            '  <div class="initials demo-photo-avatar">AM<img src="https://i.pravatar.cc/240?img=12" alt="Alex Morgan" loading="lazy"></div>',
            '  <div>',
            '    <div class="verified-name-line">',
            '      <strong>Alex Morgan</strong>' + badgeSvg,
            '      <span class="conversation-time-meta">42m ago</span>',
            '    </div>',
            '    <small>Coffee near the main hall in 15 minutes? ☕</small>',
            '  </div>',
            '  <span class="activity-unread-dot" aria-label="Unread message"></span>',
            '</div>'
          ].join('\n');
        } else if (variant === 'presence-control-row' || variant.includes('presence')) {
          newHtml = [
            '<div class="journey-person">',
            '  <div class="initials demo-photo-avatar">AM<img src="https://i.pravatar.cc/240?img=12" alt="Alex Morgan" loading="lazy"></div>',
            '  <div>',
            '    <div class="verified-name-line">',
            '      <strong>Alex Morgan</strong>' + badgeSvg,
            '    </div>',
            '    <small>Presence visible</small>',
            '  </div>',
            '  <button type="button" class="journey-presence-btn journey-row-icon-btn" aria-label="Hide presence" title="Hide presence">',
            '    <i class="ph ph-eye" aria-hidden="true"></i>',
            '  </button>',
            '</div>'
          ].join('\n');
        } else if (variant === 'unread-notice' || variant.includes('unread')) {
          newHtml = [
            '<div class="journey-person">',
            '  <div class="initials demo-photo-avatar">AM<img src="https://i.pravatar.cc/240?img=12" alt="Alex Morgan" loading="lazy"></div>',
            '  <div>',
            '    <div class="verified-name-line">',
            '      <strong>Alex Morgan</strong>' + badgeSvg,
            '    </div>',
            '    <small>Senior Product Designer</small>',
            '  </div>',
            '  <button type="button" class="has-unread" aria-label="View profile for Alex Morgan (1 unread message)">',
            '    View',
            '    <span class="network-unread-indicator" aria-hidden="true">',
            '      <span class="network-unread-dot"></span>',
            '      <span class="network-unread-ring ring-1" aria-hidden="true"></span>',
            '      <span class="network-unread-ring ring-2" aria-hidden="true"></span>',
            '    </span>',
            '    <span class="sr-only network-unread-sr">1 unread message</span>',
            '  </button>',
            '</div>'
          ].join('\n');
        } else {
          // Connected (default)
          newHtml = [
            '<div class="journey-person">',
            '  <div class="initials demo-photo-avatar">AM<img src="https://i.pravatar.cc/240?img=12" alt="Alex Morgan" loading="lazy"></div>',
            '  <div>',
            '    <div class="verified-name-line">',
            '      <strong>Alex Morgan</strong>' + badgeSvg,
            '    </div>',
            '    <small>Senior Product Designer</small>',
            '  </div>',
            '  <button type="button" aria-label="View profile for Alex Morgan">View</button>',
            '</div>'
          ].join('\n');
        }

        const temp = document.createElement('div');
        temp.innerHTML = newHtml;
        const newRow = temp.firstElementChild;
        row.replaceWith(newRow);

        const presBtn = newRow.querySelector('.journey-presence-btn');
        if (presBtn) {
          presBtn.addEventListener('click', () => {
            const isHidden = presBtn.classList.contains('is-hidden');
            presBtn.classList.toggle('is-hidden', !isHidden);
            presBtn.setAttribute('aria-label', isHidden ? 'Hide presence' : 'Unhide presence');
            presBtn.setAttribute('title', isHidden ? 'Hide presence' : 'Unhide presence');
            const icon = presBtn.querySelector('.ph');
            if (icon) icon.className = isHidden ? 'ph ph-eye' : 'ph ph-eye-slash';
            const sub = newRow.querySelector('small');
            if (sub) sub.textContent = isHidden ? 'Presence visible' : 'Presence hidden';
            updateCardHandoff(card);
          });
        }
      }
    } else if (comp === 'activity-item') {
      const titleEl = preview.querySelector('.activity-title, .activity-top-line strong, .activity-head strong');
      const sub = preview.querySelector('.activity-subtitle, [class*="subtitle"], p');
      const timeEl = preview.querySelector('.activity-time');
      const actions = preview.querySelector('.activity-actions, [class*="actions"]');
      const av = preview.querySelector('.activity-avatar');

      if (variant.includes('system')) {
        if (titleEl && !titleEl._origTitle) {
          titleEl._origTitle = titleEl.textContent;
          titleEl.textContent = 'Nearby visibility session ended';
        }
        if (sub && !sub._origSub) {
          sub._origSub = sub.textContent;
          sub.textContent = 'Session ended automatically · 5m presence window expired';
        }
        if (timeEl && !timeEl._origTime) {
          timeEl._origTime = timeEl.textContent;
          timeEl.textContent = '1h ago';
        }
        if (av && !av._origHtml) {
          av._origHtml = av.innerHTML;
          av.innerHTML = '<i class="ph ph-bell" aria-hidden="true"></i>';
          av.classList.add('system-avatar');
        }
        if (actions) actions.style.display = 'none';
      } else {
        if (titleEl && titleEl._origTitle) {
          titleEl.textContent = titleEl._origTitle;
          delete titleEl._origTitle;
        }
        if (sub && sub._origSub) {
          sub.textContent = sub._origSub;
          delete sub._origSub;
        }
        if (timeEl && timeEl._origTime) {
          timeEl.textContent = timeEl._origTime;
          delete timeEl._origTime;
        }
        if (av && av._origHtml) {
          av.innerHTML = av._origHtml;
          av.classList.remove('system-avatar');
          cleanEmptyAttrs(av);
          delete av._origHtml;
        }
        if (actions) {
          actions.style.removeProperty('display');
          cleanEmptyAttrs(actions);
        }
      }
    } else if (comp === 'list') {
      let targetEl = preview.querySelector('.settings-group, .help-faq-group') || preview;
      if (targetEl) {
        let newHtml = '';
        if (variant === 'faq-accordion' || variant.includes('faq') || variant.includes('accordion')) {
          newHtml = [
            '<div class="help-faq-group">',
            '  <div class="help-faq-item open" data-cat="privacy">',
            '    <button type="button" class="help-faq-q" aria-expanded="true">',
            '      <span>How does "Invisible by Default" work?</span>',
            '      <i class="ph ph-caret-down" aria-hidden="true"></i>',
            '    </button>',
            '    <div class="help-faq-a">',
            '      <p>You remain invisible to all nearby members until you intentionally start a discovery session. Each session requires choosing a clear networking goal and duration (30 min, 1 hour, or 2 hours). When time expires, you automatically return to invisible mode.</p>',
            '    </div>',
            '  </div>',
            '  <div class="help-faq-item" data-cat="privacy">',
            '    <button type="button" class="help-faq-q" aria-expanded="false">',
            '      <span>Can anyone see my exact address or GPS pin?</span>',
            '      <i class="ph ph-caret-down" aria-hidden="true"></i>',
            '    </button>',
            '    <div class="help-faq-a">',
            '      <p>Never. Peopi calculates approximate proximity within a randomized radius. Exact coordinates are never broadcast to other users, shared with third parties, or logged on servers.</p>',
            '    </div>',
            '  </div>',
            '  <div class="help-faq-item" data-cat="safety">',
            '    <button type="button" class="help-faq-q" aria-expanded="false">',
            '      <span>Recommendations for safe in-person meetups</span>',
            '      <i class="ph ph-caret-down" aria-hidden="true"></i>',
            '    </button>',
            '    <div class="help-faq-a">',
            '      <p>Always arrange first meetings in public, populated spaces such as open cafes, hotel lobbies, or conference lounges. Share approximate location only, and feel free to end sessions or go invisible anytime with one tap.</p>',
            '    </div>',
            '  </div>',
            '</div>'
          ].join('\n');
        } else if (variant === 'privacy-legal' || variant.includes('privacy') || variant.includes('legal')) {
          newHtml = [
            '<div class="settings-group">',
            '  <div class="settings-label">PRIVACY & LEGAL</div>',
            '  <button class="settings-item" type="button" id="settings-privacy-policy">',
            '    <span class="settings-ico"><i class="ph ph-shield-check" aria-hidden="true"></i></span>',
            '    <span><strong>Privacy Policy</strong><small>Data protection, zero ads, no GPS logging</small></span>',
            '    <i class="ph ph-caret-right" aria-hidden="true"></i>',
            '  </button>',
            '  <button class="settings-item" type="button" id="settings-terms">',
            '    <span class="settings-ico"><i class="ph ph-file-text" aria-hidden="true"></i></span>',
            '    <span><strong>Terms of Service</strong><small>Professional conduct & community safety</small></span>',
            '    <i class="ph ph-caret-right" aria-hidden="true"></i>',
            '  </button>',
            '  <button class="settings-item" type="button" id="settings-standards">',
            '    <span class="settings-ico"><i class="ph ph-handshake" aria-hidden="true"></i></span>',
            '    <span><strong>Community & Safety Standards</strong><small>Zero harassment, respectful networking</small></span>',
            '    <i class="ph ph-caret-right" aria-hidden="true"></i>',
            '  </button>',
            '</div>'
          ].join('\n');
        } else {
          // Account Settings (default)
          newHtml = [
            '<div class="settings-group">',
            '  <div class="settings-label">ACCOUNT</div>',
            '  <button type="button" class="settings-item" id="settings-profile">',
            '    <span class="settings-ico"><i class="ph ph-user-circle-gear" aria-hidden="true"></i></span>',
            '    <span><strong>Edit profile</strong><small>Your professional profile</small></span>',
            '    <i class="ph ph-caret-right" aria-hidden="true"></i>',
            '  </button>',
            '  <button type="button" class="settings-item" id="settings-verification">',
            '    <span class="settings-ico"><i class="ph ph-seal-check" aria-hidden="true"></i></span>',
            '    <span><strong>Verification</strong><small>Optional trust signals</small></span>',
            '    <i class="ph ph-caret-right" aria-hidden="true"></i>',
            '  </button>',
            '  <button type="button" class="settings-item" id="settings-privacy">',
            '    <span class="settings-ico"><i class="ph ph-shield-check" aria-hidden="true"></i></span>',
            '    <span><strong>Privacy & safety</strong><small>Visibility and safety</small></span>',
            '    <i class="ph ph-caret-right" aria-hidden="true"></i>',
            '  </button>',
            '</div>'
          ].join('\n');
        }

        const temp = document.createElement('div');
        temp.innerHTML = newHtml;
        const newGroup = temp.firstElementChild;
        targetEl.replaceWith(newGroup);

        newGroup.querySelectorAll('.help-faq-q').forEach(btn => {
          btn.addEventListener('click', () => {
            const item = btn.closest('.help-faq-item');
            if (!item) return;
            const isOpen = item.classList.contains('open');
            item.classList.toggle('open', !isOpen);
            btn.setAttribute('aria-expanded', String(!isOpen));
            updateCardHandoff(card);
          });
        });
      }
    } else if (comp === 'identity-card') {
      const nameEl = preview.querySelector('#own-name, [id="own-name"], h3');
      const titleEl = preview.querySelector('#own-title, [id="own-title"], p');
      const avatarEl = preview.querySelector('.myprofile-avatar');
      const fill = preview.querySelector('.completion-track i, .track i');
      const pct = preview.querySelector('.completion-top b, b');
      if (variant.includes('incomplete')) {
        if (nameEl) nameEl.textContent = 'Your name';
        if (titleEl) titleEl.textContent = 'Add your professional headline...';
        if (avatarEl) avatarEl.textContent = 'YN';
        if (fill) fill.style.width = '60%';
        if (pct) pct.textContent = '60%';
      } else {
        if (nameEl) nameEl.textContent = 'Alex Morgan';
        if (titleEl) titleEl.textContent = 'Product & Experience Designer';
        if (avatarEl) avatarEl.textContent = 'AM';
        if (fill) fill.style.width = '100%';
        if (pct) pct.textContent = '100%';
      }
    } else if (comp === 'avatar') {
      const av = preview.querySelector('.avatar, .myprofile-avatar');
      if (av) {
        if (variant.includes('initials')) {
          av.replaceChildren();
          av.textContent = 'AM';
          av.style.backgroundColor = '#e1c9c6';
          av.style.color = '#141922';
        } else {
          av.replaceChildren();
          const img = document.createElement('img');
          img.src = (typeof demoPortraits !== 'undefined' && demoPortraits[0]) || 'https://i.pravatar.cc/240?img=12';
          img.alt = 'Alex Morgan';
          img.loading = 'lazy';
          av.appendChild(img);
          av.style.removeProperty('background-color');
          av.style.removeProperty('color');
          cleanEmptyAttrs(av);
        }
      }
    } else if (comp === 'chip') {
      const chips = preview.querySelectorAll('.chip, .myprofile-chip, span');
      if (variant.includes('active')) {
        if (chips[0]) {
          chips[0].style.borderColor = '#ff3300';
          chips[0].style.backgroundColor = 'rgba(255, 51, 0, 0.08)';
        }
      } else if (chips[0]) {
        chips[0].style.removeProperty('border-color');
        chips[0].style.removeProperty('background-color');
        cleanEmptyAttrs(chips[0]);
      }
    } else if (comp === 'profile-progress') {
      const fill = preview.querySelector('.completion-track i, .track i, .completion-fill, [class*="fill"]');
      const txt = preview.querySelector('.completion-top b, .complete-pct, b');
      if (variant.includes('65')) {
        if (fill) fill.style.width = '65%';
        if (txt) txt.textContent = '65%';
      } else {
        if (fill) fill.style.width = '100%';
        if (txt) txt.textContent = '100%';
      }
    } else if (comp === 'profile-menu') {
      const items = preview.querySelectorAll('.myprofile-menu-item, button, .menu-row');
      items.forEach(it => {
        it.style.removeProperty('background-color');
        cleanEmptyAttrs(it);
      });
    } else if (comp === 'content-section') {
      const h3 = preview.querySelector('h3');
      const p = preview.querySelector('p');
      if (variant.includes('experience')) {
        if (h3) h3.textContent = 'Experience';
        if (p) p.textContent = 'Senior Product Designer at Studio Monolith (2023 — Present)';
      } else {
        if (h3) h3.textContent = 'About';
        if (p) p.textContent = 'I turn messy early-stage ideas into clear product experiences.';
      }
    } else if (comp === 'verified-badge') {
      const badge = preview.querySelector('.li-verified-badge');
      if (badge) {
        badge.style.removeProperty('display');
        cleanEmptyAttrs(badge);
      }
    } else if (comp === 'profile-documents') {
      const isLocked = !variant.startsWith('unlocked') && variant.includes('locked');
      const cards = preview.querySelectorAll('.peopi-doc-card');
      const list = preview.querySelector('.peopi-docs-grid, #ds-specimen-myprofile-docs-list');
      let lockHint = preview.querySelector('.connection-docs-locked-hint');
      
      const docSpecs = [
        { title: 'CV / Resume', file: 'Sahin_Erdemir_Resume.pdf', ext: 'pdf', size: '2.4 MB' },
        { title: 'One Pager', file: 'Product_Vision_OnePager.docx', ext: 'docx', size: '1.1 MB' },
        { title: 'Portfolio Deck', file: 'Selected_Works_2026.png', ext: 'png', size: '4.8 MB' }
      ];

      cards.forEach((c, idx) => {
        const info = c.querySelector('.peopi-doc-info');
        const fileEl = c.querySelector('.peopi-doc-filename');
        let lockTag = c.querySelector('.peopi-doc-lock-tag');
        const spec = docSpecs[idx] || { title: 'Document', file: 'document.pdf', ext: 'pdf', size: '1.0 MB' };

        c.classList.toggle('doc-locked', isLocked);
        if (info) info.classList.toggle('peopi-doc-blurred', isLocked);

        if (isLocked) {
          c.setAttribute('aria-label', 'Attached document (Unlocks after connecting)');
          if (fileEl) fileEl.textContent = '••••••••••••••••.' + spec.ext;
          if (!lockTag) {
            lockTag = document.createElement('div');
            lockTag.className = 'peopi-doc-lock-tag';
            lockTag.innerHTML = '<i class="ph ph-lock-key" aria-hidden="true"></i><span>Connect to view</span>';
            c.appendChild(lockTag);
          }
        } else {
          c.setAttribute('aria-label', spec.title + ' (' + spec.ext.toUpperCase() + ')');
          if (fileEl) fileEl.textContent = spec.file;
          if (lockTag) lockTag.remove();
        }
      });

      if (isLocked) {
        if (!lockHint && list) {
          lockHint = document.createElement('p');
          lockHint.className = 'connection-docs-locked-hint';
          lockHint.style.cssText = 'margin-top:14px;font-size:12px;color:var(--ink-secondary,#64748B);display:flex;align-items:center;gap:6px;';
          lockHint.innerHTML = '<i class="ph ph-lock-key" aria-hidden="true"></i> Documents unlock after connecting.';
          list.after(lockHint);
        }
      } else {
        if (lockHint) lockHint.remove();
      }
    } else if (comp === 'connection-request') {
      const isSent = variant.includes('sent');
      setConnectionRequestState(preview, isSent);
    } else if (comp === 'chat-bubble') {
      const rows = preview.querySelectorAll('.chat-row');
      rows.forEach((r, idx) => {
        if (variant === 'full-thread') {
          r.style.removeProperty('display');
          cleanEmptyAttrs(r);
        } else if (variant === 'received-only') {
          if (idx === 0) {
            r.style.removeProperty('display');
            cleanEmptyAttrs(r);
          } else {
            r.style.display = 'none';
          }
        } else if (variant === 'sent-only') {
          if (idx === 1) {
            r.style.removeProperty('display');
            cleanEmptyAttrs(r);
          } else {
            r.style.display = 'none';
          }
        }
      });
    } else if (comp === 'chat-composer') {
      const ta = preview.querySelector('input, textarea');
      const sBtn = preview.querySelector('button[type="submit"], button.chat-send-btn, button:last-child');
      if (variant.includes('typing')) {
        const draft = 'Coffee near the main hall in 15 minutes? ☕';
        if (ta) { ta.value = draft; ta.setAttribute('value', draft); }
        if (sBtn) {
          sBtn.disabled = false;
          sBtn.removeAttribute('disabled');
          sBtn.removeAttribute('style');
          sBtn.style.opacity = '1';
        }
      } else {
        if (ta) { ta.value = ''; ta.removeAttribute('value'); }
        if (sBtn) {
          sBtn.removeAttribute('style');
          sBtn.removeAttribute('disabled');
          sBtn.setAttribute('disabled', '');
          sBtn.disabled = true;
          sBtn.style.opacity = '0.5';
        }
      }
    } else if (comp === 'privacy') {
      const isVisible = variant.startsWith('visible') || variant === 'visible-open';
      const dot = preview.querySelector('.dot');
      const titleEl = preview.querySelector('#privacy-presence-title, [id="privacy-presence-title"], strong');
      const descEl = preview.querySelector('#privacy-presence-description, [id="privacy-presence-description"], small');
      const iconEl = preview.querySelector('.privacy-status-icon i, i');
      const actionBtn = preview.querySelector('#privacy-presence-action, [id="privacy-presence-action"], button');
      const statusBox = preview.querySelector('.privacy-status');

      if (statusBox) statusBox.classList.toggle('status-live', isVisible);
      if (dot) dot.classList.toggle('live', isVisible);

      if (isVisible) {
        if (titleEl) titleEl.textContent = 'Discovery is active';
        if (descEl) descEl.textContent = 'Broadcasting approximate presence nearby · 45 min remaining.';
        if (iconEl) iconEl.className = 'ph ph-broadcast';
        if (actionBtn) actionBtn.innerHTML = 'Go invisible <i class="ph ph-eye-slash" aria-hidden="true"></i>';
      } else {
        if (titleEl) titleEl.textContent = 'Invisible by default';
        if (descEl) descEl.textContent = 'You are currently invisible. Visible only when you choose to start a session.';
        if (iconEl) iconEl.className = 'ph ph-eye-slash';
        if (actionBtn) actionBtn.innerHTML = 'Discover <i class="ph ph-arrow-up-right" aria-hidden="true"></i>';
      }
    } else if (comp === 'privacy-row') {
      const small = preview.querySelector('.privacy-setting-copy small, small');
      const btn = preview.querySelector('.privacy-inline, button');
      const isOff = variant.includes('off') || variant.includes('empty');
      if (small) {
        small.textContent = isOff
          ? 'Hidden list is empty · Standard presence rules apply during active sessions.'
          : '3 connections hidden · Presence concealed even during active discovery sessions.';
      }
      if (btn) {
        if (isOff) {
          btn.style.opacity = '0.6';
        } else {
          btn.style.removeProperty('opacity');
          cleanEmptyAttrs(btn);
        }
      }
    } else if (comp === 'verification-status') {
      const isConnected = variant.includes('linkedin connected') || (variant.includes('connected') && !variant.includes('not'));
      const sub = preview.querySelector('#verify-linkedin-sub, [data-ds-source-id="verify-linkedin-sub"], [id$="verify-linkedin-sub"], small');
      const connectBtn = preview.querySelector('#verify-connect, [data-ds-source-id="verify-connect"], [id$="verify-connect"]');
      const disconnectBtn = preview.querySelector('#verify-disconnect, [data-ds-source-id="verify-disconnect"], [id$="verify-disconnect"]');
      const row = preview.querySelector('.verify-row');
      const feedback = card.querySelector('.ds-specimen-feedback') || preview.querySelector('.ds-specimen-feedback');

      if (feedback) {
        feedback.hidden = true;
        feedback.textContent = '';
      }

      if (sub) {
        sub.textContent = isConnected ? 'Connected · Public profile linked' : 'Not connected';
      }
      if (connectBtn) {
        connectBtn.classList.toggle('hide', isConnected);
        if (isConnected) connectBtn.style.display = 'none';
        else {
          connectBtn.style.removeProperty('display');
          cleanEmptyAttrs(connectBtn);
        }
        if (!connectBtn._dsWired) {
          connectBtn._dsWired = true;
          connectBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            e.preventDefault();
            const c = connectBtn.closest('.ds-workbench-card');
            if (c) applyWorkbenchVariant(c, 1);
          });
        }
      }
      if (disconnectBtn) {
        disconnectBtn.classList.toggle('hide', !isConnected);
        if (isConnected) disconnectBtn.style.display = 'flex';
        else {
          disconnectBtn.style.display = 'none';
        }
        if (!disconnectBtn._dsWired) {
          disconnectBtn._dsWired = true;
          disconnectBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            e.preventDefault();
            const c = disconnectBtn.closest('.ds-workbench-card');
            if (c) applyWorkbenchVariant(c, 0);
          });
        }
      }
      if (row) {
        row.classList.toggle('is-connected', isConnected);
      }
    } else if (comp === 'toast-notification') {
      const toast = preview.querySelector('.peopi-toast-card, .toast');
      if (toast) {
        toast.style.display = 'flex';
        toast.style.opacity = '1';
        toast.style.transform = 'none';

        const iconTile = toast.querySelector('.toast-icon-tile');
        const iconI = toast.querySelector('.toast-icon-tile i');
        const titleEl = toast.querySelector('.toast-title');
        const descEl = toast.querySelector('.toast-desc');

        if (variant.includes('information')) {
          if (iconTile) iconTile.className = 'toast-icon-tile toast-icon-info';
          if (iconI) iconI.className = 'ph ph-info';
          if (titleEl) titleEl.textContent = 'Information notice';
          if (descEl) descEl.textContent = 'Social sign-in is a UI demo. OAuth is not connected yet.';
        } else if (variant.includes('success')) {
          if (iconTile) iconTile.className = 'toast-icon-tile toast-icon-success';
          if (iconI) iconI.className = 'ph ph-check';
          if (titleEl) titleEl.textContent = 'Request sent';
          if (descEl) descEl.textContent = 'Connection request sent successfully to Alex Morgan.';
        } else if (variant.includes('warning')) {
          if (iconTile) iconTile.className = 'toast-icon-tile toast-icon-warning';
          if (iconI) iconI.className = 'ph ph-warning';
          if (titleEl) titleEl.textContent = 'Location accuracy';
          if (descEl) descEl.textContent = 'Location accuracy is reduced in Private Mode.';
        }

        const dismissBtn = toast.querySelector('.toast-dismiss-btn');
        if (dismissBtn && !dismissBtn._dsWired) {
          dismissBtn._dsWired = true;
          dismissBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            toast.style.opacity = '0';
            toast.style.transform = 'translateY(-6px)';
            setTimeout(() => { toast.style.display = 'none'; }, 180);
          });
        }
      }
    } else if (comp === 'session-alert') {
      const alert = preview.querySelector('#session-alert, .session-alert, #ds-specimen-session-alert, [data-ds-source-id="session-alert"]');
      const dismissBtn = preview.querySelector('#ds-specimen-dismiss-alert, #dismiss-alert, [data-ds-source-id="dismiss-alert"], button:last-child');
      const extendBtn = preview.querySelector('#ds-specimen-extend-session, #extend-session, [data-ds-source-id="extend-session"], button:first-child');
      const resetBtn = preview.querySelector('.ds-alert-reset-btn');
      const feedback = card.querySelector('.ds-specimen-feedback') || preview.querySelector('.ds-specimen-feedback');

      if (feedback) {
        feedback.hidden = true;
        feedback.textContent = '';
      }

      if (alert) {
        alert.style.removeProperty('display');
        alert.hidden = false;
        cleanEmptyAttrs(alert);
      }
      if (resetBtn) {
        resetBtn.style.setProperty('display', 'none', 'important');
        resetBtn.hidden = true;
      }

      const hideAlertShowReset = () => {
        if (alert) {
          alert.style.setProperty('display', 'none', 'important');
          alert.hidden = true;
        }
        if (resetBtn) {
          resetBtn.style.setProperty('display', 'inline-flex', 'important');
          resetBtn.hidden = false;
        }
        if (feedback) {
          feedback.hidden = true;
          feedback.textContent = '';
        }
      };

      const restoreAlertHideReset = () => {
        if (alert) {
          alert.style.removeProperty('display');
          alert.hidden = false;
          cleanEmptyAttrs(alert);
        }
        if (resetBtn) {
          resetBtn.style.setProperty('display', 'none', 'important');
          resetBtn.hidden = true;
        }
        if (feedback) {
          feedback.hidden = true;
          feedback.textContent = '';
        }
      };

      if (dismissBtn && !dismissBtn._dsAlertWired) {
        dismissBtn._dsAlertWired = true;
        dismissBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          e.preventDefault();
          hideAlertShowReset();
        });
      }

      if (extendBtn && !extendBtn._dsAlertWired) {
        extendBtn._dsAlertWired = true;
        extendBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          e.preventDefault();
          hideAlertShowReset();
        });
      }

      if (resetBtn && !resetBtn._dsAlertWired) {
        resetBtn._dsAlertWired = true;
        resetBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          e.preventDefault();
          restoreAlertHideReset();
        });
      }
    } else if (comp === 'verification-step') {
      const principles = preview.querySelector('.verify-principles');
      if (principles) {
        const fourth = principles.querySelector('.verify-principle-expanded');
        if (fourth) fourth.remove();
      }
    } else if (comp === 'empty-state') {
      const emptyBox = preview.querySelector('.journey-empty');
      if (emptyBox) {
        const isConv = variant.includes('conversations');
        const title = isConv ? 'No active conversations' : 'No incoming requests';
        const desc = isConv ? 'Your accepted connections will appear here.' : 'New introductions will appear here.';
        emptyBox.innerHTML = '<i class="ph ph-users-three" aria-hidden="true"></i><strong>' + title + '</strong>' + desc;
      }
    } else if (comp === 'sheet') {
      const isConn = variant.includes('connected');
      setProfileSheetState(preview, isConn);
    } else if (comp === 'dialog') {
      const isSignOut = variant.includes('sign-out');
      setDialogState(preview, isSignOut);
    } else if (comp === 'exp-sheet') {
      const isEdit = variant.includes('edit');
      setExpSheetState(preview, isEdit);
    } else if (comp === 'doc-sheet') {
      const isEmpty = variant.includes('empty');
      setDocSheetState(preview, isEmpty);
    }

    updateCardHandoff(card);
  }

  // Handle window resizing to recalibrate indicators instantly without animating
  if (!window._dsWorkbenchResizeListener) {
    window._dsWorkbenchResizeListener = () => {
      all('#ds-content .ds-workbench-card[data-component="bottom-nav"] .nav').forEach(nav => {
        const cur = nav.querySelector('button.current');
        selectBottomNav(nav, cur, { animate: false });
      });
      all('#ds-content .ds-workbench-card[data-component="tabs"] .seg').forEach(seg => {
        const cur = seg.querySelector('button.chosen, button.selected');
        selectSegmented(seg, cur, { animate: false });
      });
      all('#ds-content .ds-workbench-card[data-component="request-tabs"] .journey-tabs').forEach(seg => {
        const cur = seg.querySelector('button.chosen, button.selected');
        selectSegmented(seg, cur, { animate: false });
      });
    };
    window.addEventListener('resize', window._dsWorkbenchResizeListener);
  }

  // Direct click listeners inside specimens routing through UNIFIED state/motion path
  all('#ds-content .ds-workbench-card[data-component="bottom-nav"] .nav button').forEach(b => {
    b.addEventListener('click', () => {
      const nav = b.closest('.nav');
      if (nav) selectBottomNav(nav, b);
    });
  });

  all('#ds-content .ds-workbench-card[data-component="tabs"] .seg button').forEach(b => {
    b.addEventListener('click', () => {
      const seg = b.closest('.seg');
      if (seg) selectSegmented(seg, b);
    });
  });

  all('#ds-content .ds-workbench-card[data-component="request-tabs"] .journey-tabs button').forEach(b => {
    b.addEventListener('click', () => {
      const seg = b.closest('.journey-tabs');
      if (seg) selectSegmented(seg, b);
    });
  });

  all('#ds-content .ds-workbench-card[data-component="radio"] .option').forEach(b => {
    b.addEventListener('click', () => {
      const card = b.closest('.ds-workbench-card');
      if (card) applyWorkbenchVariant(card, 0);
    });
  });

  all('#ds-content .ds-workbench-card[data-component="intent-choice"] .journey-choice').forEach(b => {
    b.addEventListener('click', () => {
      const card = b.closest('.ds-workbench-card');
      if (!card) return;
      b.classList.toggle('selected');
      b.setAttribute('aria-pressed', String(b.classList.contains('selected')));
      normalizeElementClasses(b);
      const hasAny = !!card.querySelector('.journey-choice.selected');
      setWorkbenchVariantActive(card, hasAny ? 0 : 1);
      updateCardHandoff(card);
    });
  });

  all('#ds-content .ds-variant-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const card = btn.closest('.ds-workbench-card');
      if (card) applyWorkbenchVariant(card, btn);
    });
  });

  // INITIAL STATE SYNCHRONIZATION ACROSS ALL WORKBENCH CARDS IN DS-CONTENT
  all('#ds-content .ds-workbench-card').forEach(card => {
    const activeBtn = card.querySelector('.ds-variant-btn.active, .ds-variant-btn.is-active') || card.querySelector('.ds-variant-btn');
    try {
      if (activeBtn) {
        applyWorkbenchVariant(card, activeBtn, { initial: true, animate: false });
      } else {
        updateCardHandoff(card);
      }
    } catch (err) {
      console.error('[SYNC ERROR]', card.dataset.component, err.message, err.stack);
    }
  });

  // Wire up workbench code box tabs and copy actions across all cards in ds-content
  all('#ds-content .ds-workbench-card').forEach(card => {
    const codeBox = card.querySelector('.ds-workbench-code-box');
    if (!codeBox) return;

    const btnBriefTab = codeBox.querySelector('.ds-code-tab[data-mode="brief"]');
    const btnWebTab = codeBox.querySelector('.ds-code-tab[data-mode="web"]');
    const panelBrief = codeBox.querySelector('.ds-panel-brief');
    const panelWeb = codeBox.querySelector('.ds-panel-web');
    const metaBar = codeBox.querySelector('.ds-brief-meta-bar');
    const webSubtabs = codeBox.querySelector('.ds-web-subtabs');
    const briefActions = codeBox.querySelector('.ds-btn-copy-brief');
    const webActions = codeBox.querySelector('.ds-web-actions');

    const subtabHtml = codeBox.querySelector('.ds-web-subtab[data-subtab="html"]');
    const subtabCss = codeBox.querySelector('.ds-web-subtab[data-subtab="css"]');
    const subtabJs = codeBox.querySelector('.ds-web-subtab[data-subtab="js"]');
    const contentHtml = codeBox.querySelector('.ds-web-content-html');
    const contentCss = codeBox.querySelector('.ds-web-content-css');
    const contentJs = codeBox.querySelector('.ds-web-content-js');

    if (btnBriefTab && btnWebTab) {
      btnBriefTab.addEventListener('click', () => {
        btnBriefTab.classList.add('active');
        btnWebTab.classList.remove('active');
        if (panelBrief) panelBrief.style.display = 'block';
        if (panelWeb) panelWeb.style.display = 'none';
        if (metaBar) metaBar.style.display = 'flex';
        if (webSubtabs) webSubtabs.style.display = 'none';
        if (briefActions) briefActions.style.display = 'inline-flex';
        if (webActions) webActions.style.display = 'none';
      });

      btnWebTab.addEventListener('click', () => {
        btnWebTab.classList.add('active');
        btnBriefTab.classList.remove('active');
        if (panelBrief) panelBrief.style.display = 'none';
        if (panelWeb) panelWeb.style.display = 'block';
        if (metaBar) metaBar.style.display = 'none';
        if (webSubtabs) webSubtabs.style.display = 'flex';
        if (briefActions) briefActions.style.display = 'none';
        if (webActions) webActions.style.display = 'inline-flex';
      });
    }

    const setWebSubtab = (target) => {
      [subtabHtml, subtabCss, subtabJs].forEach(st => {
        if (st) st.classList.toggle('active', st === target);
      });
      if (contentHtml) contentHtml.style.display = (target === subtabHtml) ? 'block' : 'none';
      if (contentCss) contentCss.style.display = (target === subtabCss) ? 'block' : 'none';
      if (contentJs) contentJs.style.display = (target === subtabJs) ? 'block' : 'none';
    };

    if (subtabHtml) subtabHtml.addEventListener('click', () => setWebSubtab(subtabHtml));
    if (subtabCss) subtabCss.addEventListener('click', () => setWebSubtab(subtabCss));
    if (subtabJs) subtabJs.addEventListener('click', () => setWebSubtab(subtabJs));

    const handleCopy = async (btn, textFn) => {
      const text = textFn();
      const ok = await copyToClipboard(text);
      if (ok) {
        btn.classList.add('copied');
        const orig = btn.innerHTML;
        btn.innerHTML = '<i class="ph ph-check"></i> Copied!';
        dsToast('Copied to clipboard');
        setTimeout(() => {
          btn.innerHTML = orig;
          btn.classList.remove('copied');
        }, 1800);
      } else {
        dsToast('Clipboard access denied or unavailable', 'warning');
      }
    };

    if (briefActions) {
      briefActions.addEventListener('click', () => {
        handleCopy(briefActions, () => {
          const compKey = card.dataset.component;
          const activeVariantBtn = card.querySelector('.ds-variant-btn.active, .ds-variant-btn.is-active') || card.querySelector('.ds-variant-btn');
          const activeVariantText = activeVariantBtn ? activeVariantBtn.textContent.trim() : 'Default';
          return generateAiBrief(compKey, activeVariantText, card);
        });
      });
    }

    const btnCopyWeb = codeBox.querySelector('.ds-btn-copy-web');
    if (btnCopyWeb) {
      btnCopyWeb.addEventListener('click', () => {
        handleCopy(btnCopyWeb, () => {
          const compKey = card.dataset.component;
          const activeVariantBtn = card.querySelector('.ds-variant-btn.active, .ds-variant-btn.is-active') || card.querySelector('.ds-variant-btn');
          const activeVariantText = activeVariantBtn ? activeVariantBtn.textContent.trim() : 'Default';
          const ref = generateWebReference(compKey, activeVariantText, card);
          const activeSubtab = codeBox.querySelector('.ds-web-subtab.active');
          const subtabName = activeSubtab ? activeSubtab.dataset.subtab : 'html';
          if (subtabName === 'html') return ref.htmlCode;
          if (subtabName === 'css') return ref.cssTokensCode;
          if (subtabName === 'js') {
            return ref.isStatic ? '/* No JavaScript required for this static component */\n// Semantic HTML & CSS pseudo-states only.' : ref.jsCode;
          }
          return ref.htmlCode;
        });
      });
    }

    const btnCopyAll = codeBox.querySelector('.ds-btn-copy-all');
    if (btnCopyAll) {
      btnCopyAll.addEventListener('click', () => {
        handleCopy(btnCopyAll, () => {
          const compKey = card.dataset.component;
          const activeVariantBtn = card.querySelector('.ds-variant-btn.active, .ds-variant-btn.is-active') || card.querySelector('.ds-variant-btn');
          const activeVariantText = activeVariantBtn ? activeVariantBtn.textContent.trim() : 'Default';
          return generateStandaloneHtml(compKey, activeVariantText, card);
        });
      });
    }

    // Initialize handoff content immediately
    updateCardHandoff(card);
  });
  const copyHandler=async(button)=>{
  const text=(button.dataset.copy==='token-css')?tokenCss:button.dataset.copy;
  let copied=false;
  try{
   if(navigator.clipboard&&navigator.clipboard.writeText){
    await navigator.clipboard.writeText(text);
    copied=true;
   }
  }catch(e){}
  if(!copied){
   try{
    const ta=document.createElement('textarea');
    ta.value=text;
    ta.style.position='fixed';
    ta.style.opacity='0';
    document.body.appendChild(ta);
    ta.select();
    copied=document.execCommand('copy');
    ta.remove();
   }catch(e){}
  }
  if(copied){
   button.classList.add('ds-copied');
   const msg=(button.dataset.copy==='token-css')?'Copied CSS tokens to clipboard':'Copied '+button.dataset.copy+' to clipboard';
   dsToast(msg);
   if(button.dataset.copy==='token-css'){
    const orig=button.innerHTML;
    button.innerHTML='<i class="ph ph-check" style="margin-right:6px"></i>Copied CSS!';
    setTimeout(()=>{button.innerHTML=orig;},1500);
   }
   setTimeout(()=>button.classList.remove('ds-copied'),1200);
  }
 };
 all('#ds-content [data-copy]').forEach(button=>button.addEventListener('click',()=>copyHandler(button)));

 const btnReplayMotion=document.getElementById('btn-replay-motion');
