function setDsSubgroup(btn,open){
 // Only real accordion headings may control their own child list.
 if(!btn.matches('.ds-subgroup > .ds-subgroup-toggle'))return;
 const items=btn.nextElementSibling;
 if(!items?.classList.contains('ds-subgroup-items'))return;
 btn.setAttribute('aria-expanded',String(open));
 items.hidden=!open;
 const chevron=btn.querySelector('.ds-subgroup-chevron');
 if(chevron){
  chevron.innerHTML='<i class="ph ph-'+(open?'caret-down':'caret-right')+'" aria-hidden="true"></i>';
 }
}
all('.ds-subgroup > .ds-subgroup-toggle').forEach(btn=>{
 setDsSubgroup(btn,false);
 btn.addEventListener('click',()=>{
  const open=btn.getAttribute('aria-expanded')!=='true';
  all('.ds-subgroup > .ds-subgroup-toggle').forEach(other=>setDsSubgroup(other,false));
  setDsSubgroup(btn,open);
  
 });
});

