function parseHash(){
  const raw=window.location.hash.replace(/^#\/?/,'').trim();
  if(!raw)return null;
  const [path,...rest]=raw.split('&');
  const queryString=rest.join('&');
  const params=new URLSearchParams(queryString?queryString:(path.includes('?')?path.split('?')[1]:''));
  const cleanPath=path.split('?')[0];

  if(cleanPath==='dashboard')return{type:'dashboard',view:'intro',params};
  if(cleanPath.startsWith('overview='))return{type:'dashboard',view:cleanPath.slice(9),params};
  if(cleanPath.startsWith('overview/'))return{type:'dashboard',view:cleanPath.slice(9),params};
  if(cleanPath==='changelog'||cleanPath==='dashboard/changelog')return{type:'dashboard',view:'intro',params};

  if(cleanPath.startsWith('screen='))return{type:'screen',id:cleanPath.slice(7),params};
  if(cleanPath.startsWith('screen/'))return{type:'screen',id:cleanPath.slice(7),params};
  if(cleanPath.startsWith('ds='))return{type:'ds',id:cleanPath.slice(3),params};
  if(cleanPath.startsWith('ds/'))return{type:'ds',id:cleanPath.slice(3),params};

  if(typeof specs!=='undefined'&&specs[cleanPath])return{type:'screen',id:cleanPath,params};
  if(typeof dsData!=='undefined'&&dsData[cleanPath])return{type:'ds',id:cleanPath,params};

  return null;
}

function syncRouteFromHash(){
  const route=parseHash();
  isSyncingHash=true;
  window.isSyncingHash=true;
  try{
    if(!route||route.type==='dashboard'){
      openOverview(route&&route.view&&route.view!=='changelog'?route.view:'intro');
    }else if(route.type==='ds'){
      closeDashboard();
      if(route.params&&(route.params.get('mode')==='dark'||route.params.get('dark')==='true')) { window.peopiAllowedThemePreference = 'dark'; }
      else if(route.params&&route.params.get('mode')==='light') { window.peopiAllowedThemePreference = 'light'; }
      document.body.classList.remove('dark');
      showDesign(route.id);
      if(route.params&&route.params.has('target')){
        const targetId=route.params.get('target');
        setTimeout(()=>{
          const el=document.getElementById(targetId);
          if(el)el.scrollIntoView({behavior:'smooth',block:'start'});
        },180);
      }
    }else if(route.type==='screen'){
      closeDashboard();
      closeDesign();
      if(route.params&&route.params.has('person')){
        setJourneyView(Number(route.params.get('person')));
      }
      if(route.id==='requests'){
        journey.requestTab=route.params&&route.params.has('tab')?route.params.get('tab'):'received';
      }
      if(route.id==='messages'){
        journey.messagesTab=route.params&&route.params.has('tab')?route.params.get('tab'):'current';
      }
      if(route.id==='profile'){
        go('active');
        const pId = route.params && route.params.has('person')
          ? Number(route.params.get('person'))
          : (typeof person === 'number' && person !== null ? person : 2);
        showPerson(pId);
        openProfile();
        renderSpec('profile');
        return;
      }
      go(route.id);
    }
  }finally{
    requestAnimationFrame(()=>{isSyncingHash=false;window.isSyncingHash=false;});
  }
}

const prevGoForHash=go;
go=function(to,dir){
  prevGoForHash(to,dir);
  if(!isSyncingHash){
    setHash('screen='+to);
  }
};

const prevShowDesignForHash=showDesign;
showDesign=function(key, targetId){
  prevShowDesignForHash(key);
  if(!isSyncingHash){
    setHash('ds='+key+(targetId?'&target='+targetId:''));
  }
  if(targetId){
    setTimeout(()=>{
      const el=document.getElementById(targetId);
      if(el)el.scrollIntoView({behavior:'smooth',block:'start'});
    },180);
  }
};

window.addEventListener('hashchange',()=>{
  if(isSyncingHash)return;
  syncRouteFromHash();
});

renderDiscoveryList();
if(window.location.hash&&window.location.hash!=='#'&&window.location.hash!=='#dashboard'){
  syncRouteFromHash();
}else{
  renderSpec('closed');
  openDashboard();

}
if(document.readyState==='complete')refreshIcons();else window.addEventListener('load',refreshIcons);

/* Keep range progress aligned with its actual min/max/value, including dynamically rendered DS pages. */
(function(){
 const progress=input=>{const min=Number(input.min||0),max=Number(input.max||100),value=Number(input.value);const pct=max>min?Math.max(0,Math.min(100,(value-min)/(max-min)*100)):0;input.style.setProperty('--range-progress',pct+'%')};
 const root=document.body;
 root.addEventListener('input',e=>{if(e.target.matches('input[type="range"]'))progress(e.target)});
 const observer=new MutationObserver(()=>document.querySelectorAll('input[type="range"]').forEach(progress));
 observer.observe(document.getElementById('ds-content')||root,{childList:true,subtree:true});
 document.querySelectorAll('input[type="range"]').forEach(progress);
})();

/* ==========================================================================
   Collapsible Notes Panel & Responsive Hamburger Menu Controller
   ========================================================================== */
function setMobileMenuOpen(open){
  const isOpen = Boolean(open);
  if(isOpen && window.innerWidth <= 960 && document.body.classList.contains('notes-open')){
    setNotesOpen(false);
  }
  document.body.classList.toggle('mobile-menu-open', isOpen);
  const menuBtn = document.getElementById('mobile-menu-toggle');
  if(menuBtn){
    menuBtn.setAttribute('aria-expanded', String(isOpen));
    menuBtn.classList.toggle('active', isOpen);
    menuBtn.setAttribute('aria-label', isOpen ? 'Close navigation menu' : 'Open navigation menu');
    menuBtn.setAttribute('title', isOpen ? 'Close menu' : 'Menu');
    const icon = menuBtn.querySelector('i');
    if(icon){
      icon.className = isOpen ? 'ph ph-x' : 'ph ph-list';
    }
  }
}

function toggleMobileMenu(){
  setMobileMenuOpen(!document.body.classList.contains('mobile-menu-open'));
}

function setNotesOpen(open){
  const isOpen = Boolean(open);
  if(isOpen && window.innerWidth <= 960 && document.body.classList.contains('mobile-menu-open')){
    setMobileMenuOpen(false);
  }
  document.body.classList.toggle('notes-open', isOpen);
  const stageBtn = document.getElementById('stage-notes-toggle');
  const dsBtn = document.getElementById('ds-notes-toggle');
  const dashBtn = document.getElementById('dash-notes-toggle');
  [stageBtn, dsBtn, dashBtn].forEach(b => {
    if(b){
      b.setAttribute('aria-pressed', String(isOpen));
      b.classList.toggle('active', isOpen);
      b.setAttribute('title', isOpen ? 'Close notes panel' : 'Open notes panel');
    }
  });
  if(typeof refreshIcons === 'function') refreshIcons();
  if(typeof resizePhonePreview === 'function') requestAnimationFrame(resizePhonePreview);
}

function toggleNotes(){
  setNotesOpen(!document.body.classList.contains('notes-open'));
}

document.querySelectorAll('#stage-notes-toggle, #ds-notes-toggle, #dash-notes-toggle').forEach(btn => {
  btn.addEventListener('click', toggleNotes);
});

const mobileMenuBtn = document.getElementById('mobile-menu-toggle');
if(mobileMenuBtn){
  mobileMenuBtn.addEventListener('click', toggleMobileMenu);
}

const workspaceBackdrop = document.getElementById('workspace-overlay-backdrop');
if(workspaceBackdrop){
  workspaceBackdrop.addEventListener('click', () => {
    if(document.body.classList.contains('mobile-menu-open')) setMobileMenuOpen(false);
    if(document.body.classList.contains('notes-open')) setNotesOpen(false);
  });
}

const sidebarDrawer = document.getElementById('sidebar-nav-drawer');
if(sidebarDrawer){
  sidebarDrawer.addEventListener('click', event => {
    const link = event.target.closest('.tree-link');
    if(link && !link.classList.contains('category-toggle') && !link.classList.contains('group-toggle') && !link.classList.contains('ds-subgroup-toggle')){
      if(window.innerWidth <= 960){
        setMobileMenuOpen(false);
      }
    }
  });
}

window.addEventListener('resize', () => {
  if(window.innerWidth > 960 && document.body.classList.contains('mobile-menu-open')){
    setMobileMenuOpen(false);
  }
});

document.addEventListener('keydown', event => {
  if (event.key === 'Escape') {
    const activeModal = document.querySelector('.modal:not(.hide)');
    if (activeModal) return;
    if (document.body.classList.contains('mobile-menu-open')) {
      setMobileMenuOpen(false);
    } else if (document.body.classList.contains('notes-open')) {
      setNotesOpen(false);
    }
  }
});

/* ==========================================================================
   How Peopi Works - Lightbox Modal & Accordion Controller
   ========================================================================== */
function openHowModal(screenId, title, desc) {
  const modal = document.getElementById('how-preview-modal');
  if(!modal) return;
  const titleEl = document.getElementById('how-modal-title');
  const descEl = document.getElementById('how-modal-desc');
  const frameEl = document.getElementById('how-modal-frame');
  const jumpBtn = document.getElementById('how-modal-jump-btn');

  if(titleEl) titleEl.textContent = title;
  if(descEl) descEl.textContent = desc;
  if(jumpBtn) {
    jumpBtn.setAttribute('data-jump', screenId);
    jumpBtn.onclick = function(e) {
      e.stopPropagation();
      closeHowModal();
      if(typeof go === 'function') go(screenId);
    };
  }

  if(frameEl) {
    frameEl.innerHTML = `
      <div style="background:#0F172A;color:#FFF;padding:8px 16px;display:flex;justify-content:space-between;font-size:11px;font-weight:700;">
        <span>9:41</span>
        <span>Peopi</span>
        <span>100%</span>
      </div>
      <div style="padding:24px 20px;min-height:260px;background:#FAFAFA;display:flex;flex-direction:column;justify-content:center;text-align:center;">
        <div style="width:48px;height:48px;border-radius:14px;background:#FFF0EB;color:#FF3300;display:inline-flex;align-items:center;justify-content:center;font-size:24px;margin:0 auto 12px;border:1px solid rgba(255,51,0,0.2);">
          <i class="ph ph-device-mobile"></i>
        </div>
        <h4 style="margin:0 0 6px;font-size:16px;font-weight:800;color:#0F172A;">${title}</h4>
        <div style="display:inline-block;margin:0 auto 16px;padding:3px 10px;background:#E2E8F0;border-radius:6px;font-size:11px;font-weight:700;color:#475569;">
          Target ID: #${screenId}
        </div>
        <p style="margin:0;font-size:13px;line-height:1.5;color:#64748B;">
          ${desc}
        </p>
      </div>
    `;
  }

  modal.hidden = false;
  modal.classList.add('is-active');
  document.body.style.overflow = 'hidden';
  const closeBtn = modal.querySelector('.how-modal-close');
  if(closeBtn) closeBtn.focus();
}

function closeHowModal() {
  const modal = document.getElementById('how-preview-modal');
  if(!modal) return;
  modal.classList.remove('is-active');
  modal.hidden = true;
  document.body.style.overflow = '';
}

document.addEventListener('keydown', function(e) {
  if(e.key === 'Escape') {
    const modal = document.getElementById('how-preview-modal');
    if(modal && !modal.hidden) {
      closeHowModal();
    }
  }
});

// Setup accordion listeners for How It Works
document.addEventListener('click', function(e) {
  const trigger = e.target.closest('.how-acc-trigger');
  if(!trigger) return;
  const isExpanded = trigger.getAttribute('aria-expanded') === 'true';
  const panelId = trigger.getAttribute('aria-controls');
  const panel = document.getElementById(panelId);

  // Toggle state
  trigger.setAttribute('aria-expanded', String(!isExpanded));
  if(panel) {
    panel.hidden = isExpanded;
  }
});


