let sitemapCurrentZoom = 1.0;
let sitemapSelectedNodeId = 'active';
let sitemapSelectedJourneyId = 'journey-first-time';
let sitemapIsListView = false;
let sitemapInitialized = false;

function initSitemap() {
  if (sitemapInitialized) return;
  sitemapInitialized = true;
  renderSitemapNodes('');
  renderSitemapTable();
  renderSitemapJourneyPills();
  selectSitemapNode('active');
  selectSitemapJourney('journey-first-time');
}

function renderSitemapNodes(filterText) {
  const container = document.getElementById('sitemap-canvas-inner');
  const emptyState = document.getElementById('sitemap-search-empty');
  const emptyTerm = document.getElementById('sitemap-empty-term');
  if (!container) return;

  const term = (filterText || '').trim().toLowerCase();
  const groups = [
    { key: 'onboarding', label: 'Onboarding & Auth', bg: '#FFF2EE', color: '#0F172A' },
    { key: 'discover', label: 'Discover', bg: '#FFF0EB', color: '#FF3300' },
    { key: 'connections', label: 'Connections', bg: '#EDF7F1', color: '#0F172A' },
    { key: 'profile_privacy', label: 'Profile & Privacy', bg: '#F4EFFF', color: '#0F172A' }
  ];

  let totalVisibleNodes = 0;
  let html = '';

  groups.forEach(grp => {
    const groupNodes = sitemapNodesData.filter(n => n.group === grp.key);
    const matchingNodes = groupNodes.filter(n => {
      if (!term) return true;
      return n.title.toLowerCase().includes(term) ||
             n.code.toLowerCase().includes(term) ||
             n.summary.toLowerCase().includes(term);
    });

    totalVisibleNodes += matchingNodes.length;

    html += `
      <div class="sitemap-column" data-group="${grp.key}" style="display:flex;flex-direction:column;gap:12px;">
        <div class="sitemap-col-header" style="padding:10px 14px;border-radius:10px;background:${grp.bg};text-align:center;">
          <h4 style="margin:0;font-size:13.5px;font-weight:800;color:${grp.color};letter-spacing:-0.01em;">${grp.label}</h4>
        </div>
        <div class="sitemap-col-nodes" style="display:flex;flex-direction:column;gap:10px;">
    `;

    if (matchingNodes.length === 0) {
      html += `<div style="font-size:12px;color:#94A3B8;padding:12px 8px;font-style:italic;">No matching screens in this group</div>`;
    } else {
      matchingNodes.forEach(node => {
        const isSelected = node.id === sitemapSelectedNodeId;
        const typeClass = node.type.toLowerCase(); // screen, state, overlay
        let typeBadgeColor = '#64748B';
        let typeBadgeBg = '#F1F5F9';
        if (node.type === 'Screen') { typeBadgeColor = '#0F172A'; typeBadgeBg = '#F1F5F9'; }
        else if (node.type === 'Overlay') { typeBadgeColor = '#0369A1'; typeBadgeBg = '#E0F2FE'; }
        else if (node.type === 'State') { typeBadgeColor = '#9A3412'; typeBadgeBg = '#FFEDD5'; }

        html += `
          <div id="sitemap-node-${node.id}" class="sitemap-node-card sitemap-node-${typeClass} ${isSelected ? 'active' : ''}" onclick="selectSitemapNode('${node.id}')" style="cursor:pointer;background:#FFFFFF;border-radius:10px;padding:12px;transition:all 0.15s ease;position:relative;">
            <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;">
              <span style="font-size:11px;font-weight:600;color:#94A3B8;">${node.status}</span>
              <span class="sitemap-type-tag" style="font-size:10.5px;font-weight:700;color:${typeBadgeColor};background:${typeBadgeBg};padding:2px 6px;border-radius:5px;">${node.type}</span>
            </div>
            <h5 class="sitemap-node-title" style="margin:0 0 4px;font-size:13px;font-weight:700;color:#0F172A;line-height:1.35;">${node.title}</h5>
            <p style="margin:0;font-size:11.5px;color:#64748B;line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;">${node.summary}</p>
          </div>
        `;
      });
    }

    html += `
        </div>
      </div>
    `;
  });

  container.innerHTML = html;

  if (totalVisibleNodes === 0 && term) {
    if (emptyState) emptyState.style.display = 'block';
    if (emptyTerm) emptyTerm.textContent = term;
    container.style.display = 'none';
  } else {
    if (emptyState) emptyState.style.display = 'none';
    container.style.display = 'grid';
  }
}

function selectSitemapNode(nodeId) {
  sitemapSelectedNodeId = nodeId;
  const node = sitemapNodesData.find(n => n.id === nodeId);
  if (!node) return;

  // Highlight in canvas
  document.querySelectorAll('.sitemap-node-card').forEach(c => c.classList.remove('active'));
  const card = document.getElementById('sitemap-node-' + nodeId);
  if (card) {
    card.classList.add('active');
    card.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  // Populate Right Detail Panel
  const panel = document.getElementById('sitemap-detail-content');
  if (!panel) return;

  const linkedDsHtml = node.linkedDs.map(ds => `
    <a href="javascript:void(0)" onclick="closeDashboard();showDesign('${ds}')" style="display:inline-flex;align-items:center;gap:4px;padding:4px 8px;border-radius:6px;background:#F1F5F9;color:#0F172A;font-size:11.5px;font-weight:600;text-decoration:none;border:1px solid #E2E8F0;">
      <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="9" y1="21" x2="9" y2="9"/></svg>
      ${ds}
    </a>
  `).join('');

  const rulesHtml = node.rules.map(r => `
    <a href="javascript:void(0)" onclick="openOverview('scope-rules')" style="display:inline-flex;align-items:center;gap:4px;padding:3px 8px;border-radius:6px;background:#FEF2F2;color:#DC2626;font-size:11.5px;font-weight:700;text-decoration:none;border:1px solid #FEE2E2;">
      ${r}
    </a>
  `).join('');

  const variantsHtml = node.variants.map(v => `
    <span style="font-size:11.5px;padding:3px 8px;border-radius:6px;background:#F8FAFC;border:1px solid #E2E8F0;color:#475569;font-weight:600;">${v}</span>
  `).join('');

  panel.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">
      <span style="font-size:11.5px;font-weight:600;color:#166534;background:#DCFCE7;padding:2px 8px;border-radius:6px;">${node.status}</span>
      <span style="font-size:12px;font-weight:700;color:#0284C7;background:#E0F2FE;padding:3px 8px;border-radius:6px;">${node.type}</span>
    </div>
    <h3 style="margin:0 0 4px;font-size:18px;font-weight:800;color:#0F172A;letter-spacing:-0.02em;">${node.title}</h3>
    <div style="font-size:12px;color:#64748B;font-weight:600;margin-bottom:14px;">Group: ${node.groupLabel}</div>

    <div style="margin-bottom:16px;">
      <label style="display:block;font-size:11px;font-weight:800;letter-spacing:0.04em;text-transform:uppercase;color:#94A3B8;margin-bottom:4px;">Functional Scope</label>
      <p style="margin:0;font-size:13px;line-height:1.45;color:#334155;">${node.summary}</p>
    </div>

    <div style="margin-bottom:16px;">
      <label style="display:block;font-size:11px;font-weight:800;letter-spacing:0.04em;text-transform:uppercase;color:#94A3B8;margin-bottom:6px;">Screen State Variants</label>
      <div style="display:flex;flex-wrap:wrap;gap:6px;">${variantsHtml}</div>
    </div>

    <div style="margin-bottom:16px;">
      <label style="display:block;font-size:11px;font-weight:800;letter-spacing:0.04em;text-transform:uppercase;color:#94A3B8;margin-bottom:6px;">Linked Design Components</label>
      <div style="display:flex;flex-wrap:wrap;gap:6px;">${linkedDsHtml}</div>
    </div>

    <div style="margin-bottom:20px;">
      <label style="display:block;font-size:11px;font-weight:800;letter-spacing:0.04em;text-transform:uppercase;color:#94A3B8;margin-bottom:6px;">Enforced Invariant Rules</label>
      <div style="display:flex;flex-wrap:wrap;gap:6px;">${rulesHtml}</div>
    </div>

    <div style="display:flex;flex-direction:column;gap:8px;padding-top:14px;border-top:1px solid #E2E8F0;">
      <button class="btn btn-primary" onclick="closeDashboard();go('${node.id}');" style="width:100%;display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:9px;font-weight:700;border-radius:9px;cursor:pointer;">
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/><polyline points="15 3 21 3 21 9"/><line x1="10" y1="14" x2="21" y2="3"/></svg>
        <span>Open screen in prototype</span>
      </button>
      <button class="btn btn-secondary" onclick="closeDashboard();go('${node.id}');const nTab=document.querySelector('[data-tab=\'notes\']');if(nTab)nTab.click();" style="width:100%;display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:8px;font-size:12.5px;font-weight:600;border-radius:9px;cursor:pointer;">
        <span>View screen notes</span>
      </button>
    </div>
  `;
}

function renderSitemapTable() {
  const tbody = document.getElementById('sitemap-table-body');
  if (!tbody) return;

  tbody.innerHTML = sitemapNodesData.map(node => `
    <tr style="border-bottom:1px solid #E2E8F0;transition:background 0.15s ease;">
      
      <td style="padding:10px 16px;">
        <strong style="color:#0F172A;display:block;">${node.title}</strong>
        <span style="font-size:11.5px;color:#64748B;">${node.summary}</span>
      </td>
      <td style="padding:10px 16px;color:#475569;font-weight:600;">${node.groupLabel}</td>
      <td style="padding:10px 16px;"><span style="font-size:11px;font-weight:700;padding:2px 6px;border-radius:5px;background:#F1F5F9;color:#334155;">${node.type}</span></td>
      <td style="padding:10px 16px;"><span style="font-size:11px;font-weight:700;padding:2px 6px;border-radius:5px;background:#DCFCE7;color:#166534;">${node.status}</span></td>
      <td style="padding:10px 16px;">${node.linkedDs.join(', ')}</td>
      <td style="padding:10px 16px;text-align:right;">
        <button class="btn btn-secondary" onclick="closeDashboard();go('${node.id}');" style="padding:4px 10px;font-size:12px;font-weight:700;">Open</button>
      </td>
    </tr>
  `).join('');
}

function switchSitemapView(viewType) {
  const mapBtn = document.getElementById('sitemap-tab-map');
  const journeysBtn = document.getElementById('sitemap-tab-journeys');
  const mapContainer = document.getElementById('sitemap-map-container');
  const journeysContainer = document.getElementById('sitemap-journeys-container');
  const zoomControls = document.getElementById('sitemap-zoom-controls');
  const listToggle = document.getElementById('sitemap-toggle-list');

  if (viewType === 'map') {
    if (mapBtn) { mapBtn.classList.add('active'); mapBtn.setAttribute('aria-selected', 'true'); }
    if (journeysBtn) { journeysBtn.classList.remove('active'); journeysBtn.setAttribute('aria-selected', 'false'); }
    if (mapContainer) mapContainer.style.display = 'block';
    if (journeysContainer) journeysContainer.style.display = 'none';
    if (zoomControls) zoomControls.style.display = 'inline-flex';
    if (listToggle) listToggle.style.display = 'inline-flex';
  } else {
    if (journeysBtn) { journeysBtn.classList.add('active'); journeysBtn.setAttribute('aria-selected', 'true'); }
    if (mapBtn) { mapBtn.classList.remove('active'); mapBtn.setAttribute('aria-selected', 'false'); }
    if (mapContainer) mapContainer.style.display = 'none';
    if (journeysContainer) journeysContainer.style.display = 'block';
    if (zoomControls) zoomControls.style.display = 'none';
    if (listToggle) listToggle.style.display = 'none';
  }
}

function handleSitemapSearch(query) {
  const clearBtn = document.getElementById('sitemap-search-clear');
  if (clearBtn) clearBtn.style.display = query ? 'block' : 'none';
  renderSitemapNodes(query);
}

function clearSitemapSearch() {
  const input = document.getElementById('sitemap-search-input');
  if (input) {
    input.value = '';
    handleSitemapSearch('');
    input.focus();
  }
}

function zoomSitemapCanvas(delta) {
  sitemapCurrentZoom = Math.min(1.25, Math.max(0.75, sitemapCurrentZoom + delta));
  const inner = document.getElementById('sitemap-canvas-inner');
  const val = document.getElementById('sitemap-zoom-val');
  if (inner) inner.style.transform = `scale(${sitemapCurrentZoom})`;
  if (val) val.textContent = Math.round(sitemapCurrentZoom * 100) + '%';
}

function resetSitemapZoom() {
  sitemapCurrentZoom = 1.0;
  const inner = document.getElementById('sitemap-canvas-inner');
  const val = document.getElementById('sitemap-zoom-val');
  if (inner) inner.style.transform = 'scale(1)';
  if (val) val.textContent = '100%';
}

function toggleSitemapListView() {
  sitemapIsListView = !sitemapIsListView;
  const listContainer = document.getElementById('sitemap-list-container');
  const gridLayout = document.querySelector('.sitemap-grid-layout');
  const btn = document.getElementById('sitemap-toggle-list');
  if (listContainer) listContainer.style.display = sitemapIsListView ? 'block' : 'none';
  if (gridLayout) gridLayout.style.display = sitemapIsListView ? 'none' : 'grid';
  if (btn) btn.classList.toggle('active', sitemapIsListView);
}

function renderSitemapJourneyPills() {
  const container = document.getElementById('sitemap-journey-pills');
  if (!container) return;

  container.innerHTML = sitemapJourneysData.map((j, i) => `
    <button id="sitemap-journey-btn-${j.id}" class="sitemap-journey-btn ${j.id === sitemapSelectedJourneyId ? 'active' : ''}" onclick="selectSitemapJourney('${j.id}')" style="padding:8px 14px;border-radius:9px;font-size:12.5px;font-weight:700;border:1px solid #E2E8F0;background:#FFFFFF;cursor:pointer;display:inline-flex;align-items:center;gap:6px;">
      <span style="color:#FF3300;font-weight:800;">0${i + 1}</span>
      <span>${j.title}</span>
    </button>
  `).join('');
}

function selectSitemapJourney(journeyId) {
  sitemapSelectedJourneyId = journeyId;
  const journey = sitemapJourneysData.find(j => j.id === journeyId);
  if (!journey) return;

  // Highlight pill
  document.querySelectorAll('.sitemap-journey-btn').forEach(b => b.classList.remove('active'));
  const btn = document.getElementById('sitemap-journey-btn-' + journeyId);
  if (btn) btn.classList.add('active');

  const card = document.getElementById('sitemap-journey-card');
  if (!card) return;

  const rulesHtml = journey.rules.map(r => `
    <a href="javascript:void(0)" onclick="openOverview('scope-rules')" style="display:inline-flex;align-items:center;gap:4px;padding:3px 8px;border-radius:6px;background:#FEF2F2;color:#DC2626;font-size:11.5px;font-weight:700;text-decoration:none;border:1px solid #FEE2E2;">
      ${r}
    </a>
  `).join('');

  const stepsHtml = journey.steps.map(s => `
    <div style="display:flex;gap:16px;position:relative;padding-bottom:20px;">
      <div style="display:flex;flex-direction:column;align-items:center;">
        <div style="width:28px;height:28px;border-radius:50%;background:#0F172A;color:#FFFFFF;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800;flex-shrink:0;">${s.step}</div>
        ${s.step < journey.steps.length ? '<div style="width:2px;flex:1;background:#E2E8F0;margin:4px 0;"></div>' : ''}
      </div>
      <div style="flex:1;padding-top:2px;">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;">
          
          <strong style="font-size:14px;color:#0F172A;">${s.name}</strong>
          <button class="btn btn-secondary" onclick="closeDashboard();go('${s.screenId}');" style="padding:2px 8px;font-size:11px;font-weight:700;margin-left:auto;cursor:pointer;">Open screen</button>
        </div>
        <p style="margin:0;font-size:13px;line-height:1.45;color:#475569;">${s.action}</p>
      </div>
    </div>
  `).join('');

  card.innerHTML = `
    <div style="display:flex;flex-wrap:wrap;align-items:flex-start;justify-content:space-between;gap:16px;padding-bottom:18px;border-bottom:1px solid #E2E8F0;margin-bottom:20px;">
      <div>
        <span style="color:#FF3300;font-size:11px;font-weight:800;letter-spacing:0.08em;text-transform:uppercase;">USER JOURNEY SPECIFICATION</span>
        <h3 style="margin:4px 0 6px;font-size:22px;font-weight:800;color:#0F172A;letter-spacing:-0.02em;">${journey.title}</h3>
        <p style="margin:0;font-size:13.5px;color:#64748B;line-height:1.4;">${journey.summary}</p>
      </div>
      <div style="display:flex;flex-direction:column;gap:6px;">
        <span style="font-size:11px;font-weight:800;color:#94A3B8;text-transform:uppercase;">Applicable Rules</span>
        <div style="display:flex;flex-wrap:wrap;gap:6px;">${rulesHtml}</div>
      </div>
    </div>

    <!-- Starting Preconditions -->
    <div style="background:#F8FAFC;border:1px solid #E2E8F0;border-radius:10px;padding:12px 16px;margin-bottom:24px;display:flex;align-items:center;gap:12px;">
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#0284C7" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 14 14"/></svg>
      <div>
        <strong style="font-size:12px;color:#0F172A;display:block;">Precondition / Starting State</strong>
        <span style="font-size:12.5px;color:#475569;">${journey.precondition}</span>
      </div>
    </div>

    <!-- Steps -->
    <div style="margin-bottom:24px;">
      <h4 style="margin:0 0 16px;font-size:13px;font-weight:800;letter-spacing:0.04em;text-transform:uppercase;color:#475569;">Ordered Steps &amp; Interaction Flow</h4>
      <div>${stepsHtml}</div>
    </div>

    <!-- Terminal State -->
    <div style="background:#F0FDF4;border:1px solid #BBF7D0;border-radius:10px;padding:12px 16px;display:flex;align-items:center;gap:12px;">
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#16A34A" stroke-width="2"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
      <div>
        <strong style="font-size:12px;color:#166534;display:block;">Terminal Outcome / Expected State</strong>
        <span style="font-size:12.5px;color:#15803D;">${journey.terminal}</span>
      </div>
    </div>
  `;
}

function exportScreenIndex() {
  const exportData = {
    exportedAt: new Date().toISOString(),
    project: "Peopi Prototype Specification",
    totalScreens: sitemapNodesData.length,
    groups: [
      { key: "onboarding", label: "Onboarding & Auth" },
      { key: "discover", label: "Discover" },
      { key: "connections", label: "Connections" },
      { key: "profile_privacy", label: "Profile & Privacy" }
    ],
    screens: sitemapNodesData,
    userJourneys: sitemapJourneysData
  };

  const jsonStr = JSON.stringify(exportData, null, 2);
  const blob = new Blob([jsonStr], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "peopi-screen-index.json";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", initSitemap);
} else {
  setTimeout(initSitemap, 50);
}

/* ==========================================================================
   ROADMAP CONTROLLER (Accordion & Keyboard Accessibility)
   ========================================================================== */

function toggleRoadmapStage(stageId) {
  const card = document.getElementById('roadmap-stage-' + stageId);
  if (!card) return;
  const isExpanded = card.classList.contains('expanded');
  const header = card.querySelector('.roadmap-stage-header');
  const drawer = document.getElementById('roadmap-drawer-' + stageId);
  
  card.classList.toggle('expanded', !isExpanded);
  if (header) header.setAttribute('aria-expanded', String(!isExpanded));
  if (drawer) drawer.style.display = isExpanded ? 'none' : 'block';
}

function handleRoadmapKey(e, stageId) {
  if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault();
    toggleRoadmapStage(stageId);
  }
}

